const $ = (id) => document.getElementById(id);

/**
 * Small inline SVG for chip icons only (회차 칩).
 * Bell / wand / find use emoji again (pre-SVG look).
 */
const UI_ICON_PATHS = {
  book: '<path d="M4 19.5A2.5 2.5 0 0 1 6.5 17H20"/><path d="M6.5 2H20v20H6.5A2.5 2.5 0 0 1 4 19.5v-15A2.5 2.5 0 0 1 6.5 2z"/>',
};

function uiIcon(name, size = 20, extraClass = "") {
  const body = UI_ICON_PATHS[name];
  if (!body) return "";
  const cls = ["ui-icon", name ? `ui-icon-${name}` : "", extraClass].filter(Boolean).join(" ");
  return (
    `<span class="${cls}" aria-hidden="true">`
    + `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" width="${size}" height="${size}" fill="none" `
    + `stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" focusable="false">`
    + `${body}</svg></span>`
  );
}

/**
 * JSON API helper. Network / server failures become Error with:
 *   isNetwork | isServer | offlineSafe
 * so callers can fall back to local draft storage without losing work.
 */
async function api(path, options = {}) {
  const method = String(options.method || "GET").toUpperCase();
  const trackWriting = method === "POST"
    && String(path || "").split("?")[0] === "/api/ai/assist";
  if (trackWriting) setAiPanelWriting(true);
  try {
    const headers = { ...(options.headers || {}) };
    if (options.body != null && !headers["Content-Type"]) {
      headers["Content-Type"] = "application/json";
    }
    let response;
    try {
      response = await fetch(path, {
        ...options,
        headers,
      });
    } catch (networkError) {
      const err = new Error(
        "서버에 연결할 수 없습니다. 작성 중인 글은 이 기기에 안전하게 보관됩니다.",
      );
      err.isNetwork = true;
      err.offlineSafe = true;
      err.cause = networkError;
      throw err;
    }

    let data = {};
    const rawText = await response.text().catch(() => "");
    if (rawText) {
      try {
        data = JSON.parse(rawText);
      } catch (_) {
        data = { error: rawText.slice(0, 200) || "응답을 해석하지 못했습니다." };
      }
    }
    if (!response.ok) {
      const err = new Error(
        (data && data.error) || `저장 중 문제가 생겼습니다. (${response.status})`,
      );
      err.status = response.status;
      err.isServer = response.status >= 500;
      err.offlineSafe = response.status >= 500 || response.status === 0 || response.status === 408 || response.status === 429;
      throw err;
    }
    return data;
  } catch (error) {
    if (trackWriting) throw toAiAssistError(error);
    throw error;
  } finally {
    if (trackWriting) setAiPanelWriting(false);
  }
}

/** Nested-safe busy indicator while Tory builds an assist result. */
let aiPanelWritingDepth = 0;

function setAiPanelWriting(on) {
  if (on) aiPanelWritingDepth += 1;
  else aiPanelWritingDepth = Math.max(0, aiPanelWritingDepth - 1);
  const show = aiPanelWritingDepth > 0;
  const el = $("aiWritingStatus");
  if (el) {
    el.classList.toggle("hidden", !show);
    el.toggleAttribute("hidden", !show);
  }
  $("aiPanel")?.classList.toggle("is-writing", show);
}

const AI_ASSIST_ERR_CONNECTION =
  "연결이 끊긴 것 같아요. 인터넷 확인 후 다시 시도해 주세요.";
const AI_ASSIST_ERR_GENERIC =
  "잠깐, 결과를 못 가져왔어요. 잠시 후 다시 시도해 주세요.";

function isAiAssistConnectionError(error) {
  if (!error) return false;
  if (error.isNetwork) return true;
  try {
    if (typeof navigator !== "undefined" && navigator.onLine === false) return true;
  } catch (_) { /* ignore */ }
  const msg = String(error.message || error || "");
  return /failed to fetch|networkerror|load failed|offline|연결할 수 없/i.test(msg);
}

/** Friendly Tory copy for /api/ai/assist failures (keeps original flags). */
function toAiAssistError(error) {
  const network = isAiAssistConnectionError(error);
  const err = new Error(network ? AI_ASSIST_ERR_CONNECTION : AI_ASSIST_ERR_GENERIC);
  err.cause = error;
  err.aiAssist = true;
  err.isNetwork = Boolean(error?.isNetwork) || network;
  err.isServer = Boolean(error?.isServer);
  err.offlineSafe = Boolean(error?.offlineSafe) || network;
  err.status = error?.status;
  return err;
}

function handleAiAssistError(error) {
  console.error(error);
  const friendly = error?.aiAssist ? error : toAiAssistError(error);
  toast(friendly.message || AI_ASSIST_ERR_GENERIC, 4200);
}

function isOnlineNow() {
  try {
    return navigator.onLine !== false;
  } catch (_) {
    return true;
  }
}

function isOfflineSafeError(error) {
  if (!error) return false;
  if (error.isNetwork || error.offlineSafe) return true;
  const msg = String(error.message || error || "");
  return /failed to fetch|networkerror|load failed|offline|연결/i.test(msg);
}

function hideToast() {
  const element = $("toast");
  if (!element) return;
  element.classList.remove("show");
  window.clearTimeout(toast.timer);
  if (toast.outsideHandler) {
    document.removeEventListener("pointerdown", toast.outsideHandler, true);
    toast.outsideHandler = null;
  }
}

function toast(message, durationMs, options) {
  const element = $("toast");
  if (!element) return;
  const opts = options && typeof options === "object" ? options : {};
  window.clearTimeout(toast.timer);
  if (toast.outsideHandler) {
    document.removeEventListener("pointerdown", toast.outsideHandler, true);
    toast.outsideHandler = null;
  }
  element.replaceChildren();
  if (opts.action || opts.dismissible || opts.sticky) {
    element.classList.add("has-action");
    const copy = document.createElement("span");
    copy.className = opts.detail ? "toast-copy" : "toast-message";
    if (opts.detail) {
      const text = document.createElement("span");
      text.className = "toast-message";
      text.textContent = message;
      const detail = document.createElement("span");
      detail.className = "toast-detail";
      detail.textContent = String(opts.detail);
      copy.append(text, detail);
    } else {
      copy.textContent = message;
    }
    element.appendChild(copy);
    if (opts.action?.label) {
      const btn = document.createElement("button");
      btn.type = "button";
      btn.className = "toast-action";
      btn.textContent = opts.action.label;
      btn.addEventListener("click", (event) => {
        event.preventDefault();
        event.stopPropagation();
        hideToast();
        if (typeof opts.action.onClick === "function") opts.action.onClick();
      });
      element.appendChild(btn);
    }
    const close = document.createElement("button");
    close.type = "button";
    close.className = "toast-close";
    close.setAttribute("aria-label", "닫기");
    close.textContent = "×";
    close.addEventListener("click", (event) => {
      event.preventDefault();
      event.stopPropagation();
      hideToast();
      if (typeof opts.onClose === "function") opts.onClose();
    });
    element.appendChild(close);
  } else {
    element.classList.remove("has-action");
    element.textContent = message;
  }
  element.classList.add("show");
  if (opts.sticky) {
    if (opts.closeOnOutside) {
      const outsideHandler = (event) => {
        if (element.contains(event.target)) return;
        hideToast();
        if (typeof opts.onClose === "function") opts.onClose();
      };
      toast.outsideHandler = outsideHandler;
      window.setTimeout(() => {
        if (toast.outsideHandler !== outsideHandler) return;
        document.addEventListener("pointerdown", outsideHandler, true);
      }, 0);
    }
    return;
  }
  const ms = Number(durationMs);
  toast.timer = window.setTimeout(
    () => hideToast(),
    Number.isFinite(ms) && ms > 0 ? ms : 2600,
  );
}

function escapeHtml(text) {
  return String(text).replace(/[&<>'"]/g, (character) => ({
    "&": "&amp;", "<": "&lt;", ">": "&gt;", "'": "&#39;", '"': "&quot;",
  }[character]));
}

function looksLikeHtml(text) {
  return /<\/?[a-z][\s\S]*>/i.test(String(text || ""));
}

function plainTextFromHtml(html) {
  const host = document.createElement("div");
  host.innerHTML = html || "";
  return (host.innerText || host.textContent || "").replace(/\u00a0/g, " ").trim();
}

function sanitizeEditorHtml(html) {
  const host = document.createElement("div");
  host.innerHTML = html || "";
  host.querySelectorAll("script, style, iframe, object, embed, link, meta").forEach((node) => node.remove());
  host.querySelectorAll("*").forEach((node) => {
    [...node.attributes].forEach((attr) => {
      const name = attr.name.toLowerCase();
      const value = attr.value || "";
      if (name.startsWith("on") || name === "srcdoc") node.removeAttribute(attr.name);
      if ((name === "href" || name === "src") && /^\s*javascript:/i.test(value)) {
        node.removeAttribute(attr.name);
      }
    });
  });
  return host.innerHTML;
}

function setEditorContent(raw, editorEl = null) {
  const editor = editorEl || $("sceneContent");
  if (!editor) return;
  const text = raw == null ? "" : String(raw);
  if (!text.trim()) {
    editor.innerHTML = "";
  } else if (looksLikeHtml(text)) {
    editor.innerHTML = sanitizeEditorHtml(text);
  } else {
    editor.innerHTML = escapeHtml(text).replace(/\r\n|\r|\n/g, "<br>");
  }
  // Re-attach edit/delete controls on loaded footnotes.
  if (typeof hydrateFootnoteUi === "function") hydrateFootnoteUi(editor);
  updateEditorPlaceholder(editor);
}

function stripFindHitMarkup(html) {
  // Find highlights must never be persisted into manuscript HTML.
  if (!html || !/find-hit/i.test(html)) return html || "";
  const host = document.createElement("div");
  host.innerHTML = html;
  host.querySelectorAll("mark.find-hit").forEach((mark) => {
    const parent = mark.parentNode;
    if (!parent) return;
    while (mark.firstChild) parent.insertBefore(mark.firstChild, mark);
    parent.removeChild(mark);
  });
  host.normalize?.();
  return host.innerHTML;
}

function getEditorContent(editorEl = null) {
  const editor = editorEl || $("sceneContent");
  if (!editor) return "";
  // Clone so open find-highlights are not written into saved content.
  const raw = stripFindHitMarkup(editor.innerHTML || "");
  const html = raw
    .replace(/^(?:<br\s*\/?>|\s|&nbsp;|\u200b)*$/i, "")
    .trim();
  if (!html) return "";
  // Keep image-only or sparse markup content (do not wipe on auto-save).
  const plain = plainTextFromHtml(html);
  const hasImage = /<img\b/i.test(html);
  const hasMarkup = /<[a-z][\s\S]*>/i.test(html);
  if (!plain && !hasImage && !hasMarkup) return "";
  return sanitizeEditorHtml(raw);
}

function getEditorPlainText(editorEl = null) {
  const editor = editorEl || $("sceneContent");
  if (!editor) return "";
  return (editor.innerText || editor.textContent || "").replace(/\u00a0/g, " ");
}

function isWorldbuildingMainOpen() {
  return Boolean($("worldbuildingWorkspace") && !$("worldbuildingWorkspace").classList.contains("hidden"));
}

function isSynopsisWorkspaceOpen() {
  return Boolean($("synopsisWorkspace") && !$("synopsisWorkspace").classList.contains("hidden"));
}

function isSettingsDocMainOpen() {
  return isSynopsisWorkspaceOpen() || isWorldbuildingMainOpen();
}

/** @deprecated use isSettingsDocMainOpen */
function isSynopsisMainOpen() {
  return isSettingsDocMainOpen();
}

function getActiveRichEditor() {
  if (isSynopsisWorkspaceOpen()) {
    const active = document.activeElement;
    if (active && (active.id === "synopsisContent" || active.id === "synopsisContentB")) {
      return active;
    }
    if (lastSettingsDocEditor && document.contains(lastSettingsDocEditor)) {
      return lastSettingsDocEditor;
    }
    const focusKind = state.settingsDocFocusKind || state.settingsDocKind;
    const byKind = focusKind ? getSettingsDocMainEditor(focusKind) : null;
    return byKind || $("synopsisContent");
  }
  return $("sceneContent");
}

/** Last focused settings-doc main editor (dual panes). */
let lastSettingsDocEditor = null;

function getSettingsDocMainEditor(kind) {
  if (!kind) return null;
  const a = $("synopsisContent");
  const b = $("synopsisContentB");
  if (a?.dataset?.settingsDocKind === kind) return a;
  if (b?.dataset?.settingsDocKind === kind) return b;
  return null;
}

function getSettingsDocPairKinds(kind) {
  const siblings = SETTINGS_DOC_SIBLINGS[kind];
  if (siblings && siblings.length >= 2) return siblings.slice(0, 2);
  return kind ? [kind] : [];
}

