const TEMPO_HOOK_EMOTION_TAGS = ["긴장", "해소", "반전", "설렘", "슬픔", "유머", "공포"];
const TEMPO_HOOK_EMOTION_COLORS = {
  긴장: "#c45c4a",
  해소: "#4a8f6a",
  반전: "#7a5ea8",
  설렘: "#d4789c",
  슬픔: "#4a6fa8",
  유머: "#c48a3a",
  공포: "#4a3a52",
};
const TEMPO_HOOK_REWRITE_FALLBACK_LABELS = [
  "즉각적 위기 노출형",
  "정보 공백형",
  "감정 절정형",
];

