async function sendGlumpPingpongTurn() {
  const ping = glumpErState.pingpong;
  if (!ping?.sessionId || ping.finalText || ping.checkin) return;
  if (glumpErState.busy) return;
  const input = $("glumpErPingpongInput");
  const userText = String(input?.value || "").trim();
  if (!userText) {
    toast("한 문장을 먼저 써 주세요.");
    return;
  }
  glumpErState.busy = true;
  renderGlumpErStep();
  try {
    const data = await api("/api/glump/pingpong/turn", {
      method: "POST",
      body: JSON.stringify({
        session_id: ping.sessionId,
        user_text: userText,
      }),
    });
    ping.turns = [
      ...(ping.turns || []),
      { speaker: "user", text: userText },
      { speaker: "tori", text: String(data?.tori_text || "").trim() },
    ];
    ping.checkin = Boolean(data?.checkin);
    ping.writtenChars = Number(data?.written_chars) || 0;
    if (input) input.value = "";
  } catch (error) {
    handleError(error);
  } finally {
    glumpErState.busy = false;
    renderGlumpErStep();
    if (!glumpErState.pingpong?.checkin) {
      try { $("glumpErPingpongInput")?.focus(); } catch (_) { /* ignore */ }
    }
  }
}

async function endGlumpPingpong() {
  const ping = glumpErState.pingpong;
  if (!ping?.sessionId || ping.finalText) return;
  if (glumpErState.busy) return;
  glumpErState.busy = true;
  renderGlumpErStep();
  try {
    const data = await api("/api/glump/pingpong/end", {
      method: "POST",
      body: JSON.stringify({ session_id: ping.sessionId }),
    });
    const finalText = String(data?.final_text || "").trim();
    ping.finalText = finalText;
    ping.checkin = false;
    restoreManuscriptContextRange($("sceneContent"));
    insertTextIntoSceneEditor(finalText);
  } catch (error) {
    handleError(error);
  } finally {
    glumpErState.busy = false;
    renderGlumpErStep();
  }
}

function newGlumpLuckySessionId() {
  try {
    if (typeof crypto !== "undefined" && typeof crypto.randomUUID === "function") {
      return crypto.randomUUID();
    }
  } catch (_) { /* ignore */ }
  return `lucky-${Date.now()}-${Math.random().toString(16).slice(2)}`;
}

async function runGlumpLuckySentence({ redraw = false } = {}) {
  if (!state.projectId) {
    toast("먼저 작품을 선택해 주세요.");
    return;
  }
  const episode = glumpCurrentEpisodeText();
  if (episode.length < 100) {
    toast("원고 내용이 너무 짧아요, 조금 더 써주시면 맥락을 파악할 수 있어요");
    return;
  }
  if (glumpErState.busy) return;
  if (!redraw || !glumpErState.lucky?.sessionId) {
    captureGlumpFillBlankCaret();
    glumpErState.lucky = {
      sessionId: newGlumpLuckySessionId(),
      sentence: "",
      forceChoice: false,
      options: [],
    };
  }
  glumpErState.busy = true;
  glumpErState.step = "lucky";
  renderGlumpErStep();
  playGlumpLuckyToriIntro();
  try {
    const data = await api("/api/glump/lucky-sentence", {
      method: "POST",
      body: JSON.stringify({
        work_id: state.projectId,
        session_id: glumpErState.lucky.sessionId,
        episode_content: episode,
      }),
    });
    if (data?.force_choice) {
      glumpErState.lucky.forceChoice = true;
      glumpErState.lucky.options = Array.isArray(data.previous_options) ? data.previous_options : [];
      glumpErState.lucky.sentence = "";
    } else {
      glumpErState.lucky.forceChoice = false;
      glumpErState.lucky.sentence = String(data?.sentence || "").trim();
      glumpErState.lucky.options = [];
    }
  } catch (error) {
    handleError(error);
    if (!redraw) glumpErState.step = glumpErReturnStep();
  } finally {
    glumpErState.busy = false;
    renderGlumpErStep();
  }
}

function insertGlumpLuckySentence(text) {
  const sentence = String(text || glumpErState.lucky?.sentence || "").trim();
  if (!sentence) {
    toast("넣을 문장이 없어요.");
    return;
  }
  restoreManuscriptContextRange($("sceneContent"));
  insertTextIntoSceneEditor(sentence);
}

async function runGlumpInterrogation() {
  if (!state.projectId) {
    toast("먼저 작품을 선택해 주세요.");
    return;
  }
  const episode = glumpCurrentEpisodeText();
  if (episode.length < 100) {
    toast("원고 내용이 너무 짧아요, 조금 더 써주시면 맥락을 파악할 수 있어요");
    return;
  }
  if (glumpErState.busy) return;
  glumpErState.busy = true;
  glumpErState.step = "interrogation";
  glumpErState.interrogation = null;
  renderGlumpErStep();
  playGlumpInterrogationToriIntro();
  try {
    const data = await api("/api/glump/interrogation/start", {
      method: "POST",
      body: JSON.stringify({
        work_id: state.projectId,
        episode_content: episode,
      }),
    });
    const questions = Array.isArray(data?.questions) ? data.questions : [];
    glumpErState.interrogation = {
      sessionId: data?.session_id || "",
      characterName: String(data?.character_name || "").trim(),
      qa: questions.map((question) => ({ question: String(question || "").trim(), answer: "" })),
      hints: [],
    };
  } catch (error) {
    handleError(error);
    glumpErState.step = glumpErReturnStep();
  } finally {
    glumpErState.busy = false;
    renderGlumpErStep();
  }
}

async function answerGlumpInterrogation(questionIndex) {
  const hearing = glumpErState.interrogation;
  if (!hearing?.sessionId) return;
  if (glumpErState.busy) return;
  const index = Number(questionIndex);
  if (!Number.isInteger(index) || index < 0) return;
  glumpErState.busy = true;
  renderGlumpErStep();
  try {
    const data = await api("/api/glump/interrogation/answer", {
      method: "POST",
      body: JSON.stringify({
        session_id: hearing.sessionId,
        question_index: index,
        episode_content: glumpCurrentEpisodeText(),
      }),
    });
    if (!Array.isArray(hearing.qa)) hearing.qa = [];
    if (hearing.qa[index]) {
      hearing.qa[index].answer = String(data?.answer || "").trim();
    }
  } catch (error) {
    handleError(error);
  } finally {
    glumpErState.busy = false;
    renderGlumpErStep();
  }
}

async function summarizeGlumpInterrogation() {
  const hearing = glumpErState.interrogation;
  if (!hearing?.sessionId) return;
  if (glumpErState.busy) return;
  glumpErState.busy = true;
  renderGlumpErStep();
  try {
    const data = await api("/api/glump/interrogation/summarize", {
      method: "POST",
      body: JSON.stringify({ session_id: hearing.sessionId }),
    });
    hearing.hints = Array.isArray(data?.hint_cards) ? data.hint_cards : [];
  } catch (error) {
    handleError(error);
  } finally {
    glumpErState.busy = false;
    renderGlumpErStep();
  }
}

function glumpSafeHttpUrl(value) {
  try {
    const parsed = new URL(String(value || "").trim());
    if (parsed.protocol !== "https:" && parsed.protocol !== "http:") return "";
    return parsed.href;
  } catch (_) {
    return "";
  }
}

function closeGlumpErToManuscript() {
  closeGlumpErModal({ dismissed: true, returnToList: false });
  const editor = (typeof getActiveRichEditor === "function" && getActiveRichEditor())
    || $("sceneContent");
  requestAnimationFrame(() => {
    try {
      editor?.focus({ preventScroll: true });
    } catch (_) {
      editor?.focus();
    }
  });
}

function handleGlumpDiversionExit(choice) {
  const action = String(choice || "").trim();
  if (action === "more") {
    openGlumpDiversionsStep();
    return;
  }
  if (action === "write") {
    closeGlumpErToManuscript();
    return;
  }
  toast("잘 쉬고 오세요. 한 글자도 안 써도 괜찮아요.");
  closeGlumpErModal({ dismissed: true });
}

async function copyGlumpShortText(text) {
  const value = String(text || "").trim();
  if (!value) return toast("복사할 이름이 없어요.");
  try {
    if (navigator.clipboard?.writeText) {
      await navigator.clipboard.writeText(value);
    } else {
      const helper = document.createElement("textarea");
      helper.value = value;
      helper.setAttribute("readonly", "");
      helper.style.position = "fixed";
      helper.style.left = "-9999px";
      document.body.appendChild(helper);
      helper.select();
      document.execCommand("copy");
      helper.remove();
    }
    toast("복사했어요.");
  } catch (_) {
    toast("복사에 실패했어요.");
  }
}

function renderGlumpColorCharacterBar(diversion) {
  const current = String(diversion?.character_name || "").trim();
  const isProtagonist = String(diversion?.character_role || "") === "protagonist";
  const who = current
    ? (isProtagonist
      ? `주인공 「${escapeHtml(current)}」 기준으로 뽑았어요`
      : `「${escapeHtml(current)}」 기준으로 뽑았어요`)
    : "주인공 기준으로 뽑았어요";
  const people = Array.isArray(state.characters) ? state.characters : [];
  const options = people.map((ch) => {
    const name = String(ch?.name || "").trim();
    if (!name) return "";
    const label = String(ch.role || "") === "protagonist" ? `${name} (주인공)` : name;
    const selected = name === current ? " selected" : "";
    return `<option value="${escapeHtml(name)}"${selected}>${escapeHtml(label)}</option>`;
  }).filter(Boolean).join("");
  const picker = options
    ? `<label class="glump-er-color-pick">다른 캐릭터: <select id="glumpErColorCharacter" aria-label="다른 캐릭터">${options}</select></label>`
    : "";
  return `<div class="glump-er-color-who"><p>${who}</p>${picker}</div>`;
}

function renderGlumpDiversionBody(diversion) {
  if (!diversion || diversion.error) return "";
  const kind = String(diversion.kind || "");
  if (kind === "mood_color") {
    const colors = Array.isArray(diversion.colors) ? diversion.colors : [];
    const chips = colors.map((item) => {
      const hex = String(item?.hex || "").trim();
      const safeHex = /^#[0-9A-Fa-f]{6}$/.test(hex) ? hex : "";
      const name = escapeHtml(String(item?.name || "색"));
      const reason = escapeHtml(String(item?.reason || ""));
      const swatch = safeHex
        ? `<span class="glump-er-color-swatch" style="background:${safeHex}" aria-hidden="true"></span>`
        : `<span class="glump-er-color-swatch" aria-hidden="true"></span>`;
      return `<article class="glump-er-color-chip">${swatch}<div><strong>${name}${safeHex ? ` · ${escapeHtml(safeHex)}` : ""}</strong>${reason ? `<p>${reason}</p>` : ""}</div></article>`;
    }).join("");
    return renderGlumpColorCharacterBar(diversion) + chips;
  }
  if (kind === "mood_playlist") {
    const title = escapeHtml(String(diversion.playlist_title || "가상 플레이리스트"));
    const tracks = Array.isArray(diversion.tracks) ? diversion.tracks : [];
    const trackHtml = tracks.map((item, index) => {
      const song = escapeHtml(String(item?.title || `곡 ${index + 1}`));
      const mood = escapeHtml(String(item?.mood || ""));
      return `<article class="glump-er-track-item"><strong>${index + 1}. ${song}</strong>${mood ? `<p>${mood}</p>` : ""}</article>`;
    }).join("");
    return `<p class="glump-er-playlist-title">${title}</p>${trackHtml}`;
  }
  if (kind === "mood_board") {
    const photos = Array.isArray(diversion.photos) ? diversion.photos : [];
    const cards = photos.map((item) => {
      const url = glumpSafeHttpUrl(item?.url);
      if (!url) return "";
      const photographer = escapeHtml(String(item?.photographer || ""));
      const alt = escapeHtml(String(item?.alt || photographer || "무드보드 사진"));
      const credit = photographer
        ? `<p class="glump-er-mood-credit">Photo by ${photographer}</p>`
        : "";
      return `<figure class="glump-er-mood-card"><img src="${escapeHtml(url)}" alt="${alt}">${credit}</figure>`;
    }).join("");
    return cards ? `<div class="glump-er-mood-grid">${cards}</div>` : "";
  }
  if (kind === "word_list") {
    const words = Array.isArray(diversion.words) ? diversion.words : [];
    return words.map((item) => {
      const word = escapeHtml(String(item?.word || ""));
      const nuance = escapeHtml(String(item?.nuance || ""));
      if (!word) return "";
      return `<article class="glump-er-word-item"><strong>${word}</strong>${nuance ? `<p>${nuance}</p>` : ""}</article>`;
    }).join("");
  }
  if (kind === "character_tarot") {
    const cards = Array.isArray(diversion.cards) ? diversion.cards : [];
    return cards.map((item, index) => {
      const name = escapeHtml(String(item?.name || `카드 ${index + 1}`));
      const meaning = escapeHtml(String(item?.meaning || ""));
      return `<article class="glump-er-tarot-card"><strong>${index + 1}. ${name}</strong>${meaning ? `<p>${meaning}</p>` : ""}</article>`;
    }).join("");
  }
  if (kind === "naming_shop") {
    const groups = Array.isArray(diversion.groups) ? diversion.groups : [];
    return groups.map((group) => {
      const category = escapeHtml(String(group?.category || "이름"));
      const items = Array.isArray(group?.items) ? group.items : [];
      const rows = items.map((item) => {
        const name = String(item?.name || "").trim();
        if (!name) return "";
        const nuance = escapeHtml(String(item?.nuance || ""));
        return `<article class="glump-er-naming-item"><div><strong>${escapeHtml(name)}</strong>${nuance ? `<p>${nuance}</p>` : ""}</div><button type="button" class="secondary compact-btn" data-glump-name-copy="${escapeHtml(name)}">복사</button></article>`;
      }).join("");
      return `<section class="glump-er-naming-group"><strong class="glump-er-naming-category">${category}</strong>${rows}</section>`;
    }).join("");
  }
  return "";
}

async function ensureGlumpCharacters() {
  if (!state.projectId) return [];
  if (Array.isArray(state.characters) && state.characters.length) return state.characters;
  try {
    const characters = await api(`/api/projects/${state.projectId}/characters`);
    if (Array.isArray(characters)) state.characters = characters;
  } catch (_) { /* ignore */ }
  return Array.isArray(state.characters) ? state.characters : [];
}

async function runGlumpDiversion(kind) {
  const id = String(kind || "").trim();
  if (!GLUMP_DIVERSION_META[id]) return;
  if (!state.projectId) {
    toast("먼저 작품을 선택해 주세요.");
    return;
  }
  if (glumpErState.busy) return;
  glumpErState.busy = true;
  glumpErState.step = "diversionResult";
  glumpErState.diversion = { kind: id };
  renderGlumpErStep();
  try {
    let data;
    if (id === "word_list") {
      data = await api(`/api/glump/word-list?work_id=${encodeURIComponent(state.projectId)}`);
    } else if (id === "mood_color") {
      await ensureGlumpCharacters();
      const payload = { work_id: state.projectId };
      const picked = String(glumpErState.diversionCharacterName || "").trim();
      if (picked) payload.character_name = picked;
      data = await api("/api/glump/mood-color", {
        method: "POST",
        body: JSON.stringify(payload),
      });
    } else if (id === "mood_playlist") {
      data = await api("/api/glump/mood-playlist", {
        method: "POST",
        body: JSON.stringify({ work_id: state.projectId }),
      });
    } else if (id === "character_tarot") {
      data = await api("/api/glump/character-tarot", {
        method: "POST",
        body: JSON.stringify({ work_id: state.projectId }),
      });
    } else if (id === "naming_shop") {
      data = await api("/api/glump/naming-shop", {
        method: "POST",
        body: JSON.stringify({ work_id: state.projectId }),
      });
    } else {
      data = await api("/api/glump/mood-board", {
        method: "POST",
        body: JSON.stringify({ work_id: state.projectId }),
      });
    }
    glumpErState.diversion = { kind: id, ...(data || {}) };
    if (id === "mood_color" && data?.character_name) {
      glumpErState.diversionCharacterName = String(data.character_name);
    }
  } catch (error) {
    handleError(error);
    glumpErState.diversion = {
      kind: id,
      error: true,
      message: String(error?.message || "이번에는 못 보여 줬어요."),
    };
  } finally {
    glumpErState.busy = false;
    renderGlumpErStep();
  }
}

function setupGlumpErUi() {
  $("aiMode")?.addEventListener("change", () => {
    if (isGlumpErMode()) {
      glumpErState.modalDismissed = false;
      resetGlumpErState();
    }
    updateGlumpErVisibility({ forceOpen: isGlumpErMode() });
  });

  const modal = $("glumpErModal");
  if (modal && modal.dataset.bound !== "1") {
    modal.dataset.bound = "1";
    modal.querySelectorAll("[data-close-glump-er]").forEach((el) => {
      el.addEventListener("click", (event) => {
        event.preventDefault();
        closeGlumpErModal({ dismissed: true });
      });
    });
    modal.addEventListener("change", (event) => {
      const select = event.target.closest?.("#glumpErColorCharacter");
      if (!(select instanceof HTMLSelectElement)) return;
      const name = String(select.value || "").trim();
      if (!name || name === glumpErState.diversionCharacterName) return;
      glumpErState.diversionCharacterName = name;
      runGlumpDiversion("mood_color").catch(handleError);
    });
    modal.addEventListener("click", (event) => {
      const copyBtn = event.target.closest?.("[data-glump-name-copy]");
      if (copyBtn) {
        event.preventDefault();
        copyGlumpShortText(copyBtn.getAttribute("data-glump-name-copy") || "");
        return;
      }
      const q1Btn = event.target.closest?.("[data-glump-q1]");
      if (q1Btn) {
        event.preventDefault();
        const q1 = q1Btn.getAttribute("data-glump-q1") || "";
        if (q1 === "block") {
          glumpErState.q1 = q1;
          glumpErState.q2 = "";
          glumpErState.step = "q2";
          renderGlumpErStep();
          return;
        }
        submitGlumpDiagnosis(q1).catch(handleError);
        return;
      }
      const q2Btn = event.target.closest?.("[data-glump-q2]");
      if (q2Btn) {
        event.preventDefault();
        const q2 = q2Btn.getAttribute("data-glump-q2") || "";
        submitGlumpDiagnosis(glumpErState.q1 || "block", q2).catch(handleError);
        return;
      }
      const restBtn = event.target.closest?.("[data-glump-rest]");
      if (restBtn) {
        event.preventDefault();
        const choice = restBtn.getAttribute("data-glump-rest") || "";
        if (choice === "rest") {
          toast("잘 쉬고 오세요. 한 글자도 안 써도 괜찮아요.");
          closeGlumpErModal({ dismissed: true });
        } else if (choice === "play") {
          openGlumpDiversionsStep();
        } else {
          toast("조금이라도 괜찮아요. 오늘 목표는 300자면 충분해요.");
          closeGlumpErToManuscript();
        }
        return;
      }
      const diversionBtn = event.target.closest?.("[data-glump-diversion]");
      if (diversionBtn && !event.target.closest?.("[data-glump-diversion-exit]")) {
        event.preventDefault();
        runGlumpDiversion(diversionBtn.getAttribute("data-glump-diversion") || "");
        return;
      }
      const diversionExitBtn = event.target.closest?.("[data-glump-diversion-exit]");
      if (diversionExitBtn) {
        event.preventDefault();
        handleGlumpDiversionExit(diversionExitBtn.getAttribute("data-glump-diversion-exit") || "");
        return;
      }
      if (event.target.closest?.("[data-glump-start-diagnosis]")) {
        event.preventDefault();
        glumpErState.step = "q1";
        renderGlumpErStep();
        return;
      }
      const homeTool = event.target.closest?.("[data-glump-tool]");
      if (homeTool) {
        event.preventDefault();
        launchGlumpHomeTool(homeTool.getAttribute("data-glump-tool") || "");
        return;
      }
      if (event.target.closest?.("[data-glump-open-sprint]")) {
        event.preventDefault();
        openGlumpSprintModeStep();
        return;
      }
      const sprintBtn = event.target.closest?.("[data-glump-sprint]");
      if (sprintBtn) {
        event.preventDefault();
        startGlumpSprint(sprintBtn.getAttribute("data-glump-sprint") || "");
      }
    });
  }
  $("glumpErQ1Back")?.addEventListener("click", (event) => {
    event.preventDefault();
    glumpErState.step = "home";
    renderGlumpErStep();
    playGlumpHomeToriIntro();
  });
  $("glumpErQ2Back")?.addEventListener("click", (event) => {
    event.preventDefault();
    glumpErState.step = "q1";
    glumpErState.q2 = "";
    renderGlumpErStep();
  });
  $("glumpErRestart")?.addEventListener("click", (event) => {
    event.preventDefault();
    resetGlumpErState();
    renderGlumpErStep();
    playGlumpHomeToriIntro();
  });
  $("glumpErRunTool")?.addEventListener("click", (event) => {
    event.preventDefault();
    runGlumpWildcardSpark().catch(handleError);
  });
  $("glumpErRunVitamin")?.addEventListener("click", (event) => {
    event.preventDefault();
    runGlumpMentalVitamin().catch(handleError);
  });
  $("glumpErRunFillBlank")?.addEventListener("click", (event) => {
    event.preventDefault();
    runGlumpFillBlank().catch(handleError);
  });
  $("glumpErRunPingpong")?.addEventListener("click", (event) => {
    event.preventDefault();
    runGlumpPingpong().catch(handleError);
  });
  $("glumpErRunLucky")?.addEventListener("click", (event) => {
    event.preventDefault();
    runGlumpLuckySentence().catch(handleError);
  });
  $("glumpErRunInterrogation")?.addEventListener("click", (event) => {
    event.preventDefault();
    runGlumpInterrogation().catch(handleError);
  });
  $("glumpErSparkBack")?.addEventListener("click", (event) => {
    event.preventDefault();
    glumpErState.step = glumpErReturnStep();
    renderGlumpErStep();
  });
  $("glumpErVitaminBack")?.addEventListener("click", (event) => {
    event.preventDefault();
    glumpErState.step = glumpErReturnStep();
    renderGlumpErStep();
  });
  $("glumpErFillBlankBack")?.addEventListener("click", (event) => {
    event.preventDefault();
    glumpErState.step = glumpErReturnStep();
    renderGlumpErStep();
  });
  $("glumpErFillBlankSubmit")?.addEventListener("click", (event) => {
    event.preventDefault();
    submitGlumpFillBlank().catch(handleError);
  });
  $("glumpErPingpongBack")?.addEventListener("click", (event) => {
    event.preventDefault();
    glumpErState.step = glumpErReturnStep();
    renderGlumpErStep();
  });
  $("glumpErPingpongSend")?.addEventListener("click", (event) => {
    event.preventDefault();
    sendGlumpPingpongTurn().catch(handleError);
  });
  $("glumpErPingpongEnd")?.addEventListener("click", (event) => {
    event.preventDefault();
    endGlumpPingpong().catch(handleError);
  });
  $("glumpErPingpongStop")?.addEventListener("click", (event) => {
    event.preventDefault();
    endGlumpPingpong().catch(handleError);
  });
  $("glumpErPingpongContinue")?.addEventListener("click", (event) => {
    event.preventDefault();
    if (glumpErState.pingpong) glumpErState.pingpong.checkin = false;
    renderGlumpErStep();
    try { $("glumpErPingpongInput")?.focus(); } catch (_) { /* ignore */ }
  });
  $("glumpErPingpongInput")?.addEventListener("keydown", (event) => {
    if (event.key === "Enter" && (event.ctrlKey || event.metaKey)) {
      event.preventDefault();
      sendGlumpPingpongTurn().catch(handleError);
    }
  });
  $("glumpErLuckyBack")?.addEventListener("click", (event) => {
    event.preventDefault();
    glumpErState.step = glumpErReturnStep();
    renderGlumpErStep();
  });
  $("glumpErLuckyRedraw")?.addEventListener("click", (event) => {
    event.preventDefault();
    runGlumpLuckySentence({ redraw: true }).catch(handleError);
  });
  $("glumpErLuckyInsert")?.addEventListener("click", (event) => {
    event.preventDefault();
    insertGlumpLuckySentence();
  });
  $("glumpErInterrogationBack")?.addEventListener("click", (event) => {
    event.preventDefault();
    glumpErState.step = glumpErReturnStep();
    renderGlumpErStep();
  });
  $("glumpErInterrogationSummarize")?.addEventListener("click", (event) => {
    event.preventDefault();
    summarizeGlumpInterrogation().catch(handleError);
  });
  $("glumpErInterrogationBody")?.addEventListener("click", (event) => {
    const ask = event.target.closest?.("[data-glump-interrogate]");
    if (!ask) return;
    event.preventDefault();
    const index = Number(ask.getAttribute("data-glump-interrogate"));
    answerGlumpInterrogation(index).catch(handleError);
  });
  $("glumpErLuckyBody")?.addEventListener("click", (event) => {
    const pick = event.target.closest?.("[data-glump-lucky-pick]");
    if (!pick) return;
    event.preventDefault();
    const index = Number(pick.getAttribute("data-glump-lucky-pick"));
    const text = glumpErState.lucky?.options?.[index] || pick.textContent || "";
    insertGlumpLuckySentence(text);
  });
  $("glumpErSprintBack")?.addEventListener("click", (event) => {
    event.preventDefault();
    glumpErState.step = glumpErReturnStep();
    renderGlumpErStep();
  });
  $("glumpErDiversionsBack")?.addEventListener("click", (event) => {
    event.preventDefault();
    glumpErState.step = glumpErReturnStep();
    renderGlumpErStep();
  });

  ensureGlumpSprintBindings();

  if (isGlumpErMode()) {
    updateGlumpErVisibility();
  } else {
    $("glumpErInlineHint")?.classList.add("hidden");
    closeGlumpErModal({ dismissed: false, returnToList: false });
  }
}

function ensureGlumpSprintBindings() {
  if (document.documentElement.dataset.glumpSprintBound === "1") return;
  document.documentElement.dataset.glumpSprintBound = "1";
  document.addEventListener("keydown", onGlumpSprintKeydown, true);
  $("sceneContent")?.addEventListener("beforeinput", onGlumpSprintBeforeInput);
  $("sceneContent")?.addEventListener("input", onGlumpSprintInput);
  $("manuscriptPage")?.addEventListener("scroll", scheduleGlumpSprintBlindOverlay, { passive: true });
  document.addEventListener("selectionchange", () => {
    if (glumpSprintState.active && glumpSprintState.blind) scheduleGlumpSprintBlindOverlay();
  });
  window.addEventListener("resize", () => {
    if (glumpSprintState.active && glumpSprintState.blind) scheduleGlumpSprintBlindOverlay();
  });
  window.addEventListener("beforeunload", (event) => {
    if (!glumpSprintState.active) return;
    event.preventDefault();
    event.returnValue = "";
  });
  $("glumpSprintRewardKeep")?.addEventListener("click", () => closeGlumpSprintReward());
  $("glumpSprintRewardAgain")?.addEventListener("click", () => {
    const mode = $("glumpSprintRewardModal")?.dataset.mode || "";
    closeGlumpSprintReward();
    if (mode) startGlumpSprint(mode);
  });
  document.querySelectorAll("[data-close-glump-sprint-reward]").forEach((el) => {
    el.addEventListener("click", () => closeGlumpSprintReward());
  });
}

function collectToToryVault(options = {}) {
  if (!state.projectId) {
    toast("먼저 작품을 선택해 주세요.");
    return null;
  }
  const resultText = String(options.text ?? $("aiResult")?.value ?? "").trim();
  const promptText = String(options.prompt ?? $("aiPrompt")?.value ?? "").trim();
  const body = resultText || promptText;
  if (!body) {
    toast("수집할 내용이 없어요. 토리에게 물어보거나 요청을 적어 주세요.");
    return null;
  }
  const mode = String(options.mode || $("aiMode")?.value || "free");
  const sceneTitle = state.scene?.title || $("sceneTitle")?.value || state.toryFocusSceneTitle || "";
  const list = loadToryVault();
  const item = {
    id: `vault-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 6)}`,
    title: options.title
      || (resultText ? `토리 · ${aiModeLabel(mode)}` : `요청 · ${aiModeLabel(mode)}`)
      || "수집 메모",
    body,
    prompt: promptText,
    mode,
    sceneTitle,
    createdAt: new Date().toISOString(),
  };
  list.unshift(item);
  // Cap growth
  if (list.length > 200) list.length = 200;
  saveToryVault(list);
  renderToryVaultList();
  renderSettingsCodex();
  toast("토리 수집창고에 넣었어요.");
  return item;
}

function renderToryVaultList() {
  const listEl = $("toryVaultList");
  if (!listEl) return;
  const items = loadToryVault();
  if (!items.length) {
    listEl.innerHTML = `<p class="hint tory-vault-empty">아직 수집한 내용이 없어요.<br>토리 결과 아래 <strong>수집</strong>으로 아이디어를 담아 보세요.</p>`;
    return;
  }
  listEl.innerHTML = items.map((item) => {
    const when = item.createdAt
      ? new Date(item.createdAt).toLocaleString("ko-KR", { month: "short", day: "numeric", hour: "2-digit", minute: "2-digit" })
      : "";
    const mode = escapeHtml(aiModeLabel(item.mode));
    const scene = item.sceneTitle ? escapeHtml(item.sceneTitle) : "";
    const body = escapeHtml(item.body || "");
    return `
      <article class="tory-vault-card" data-vault-id="${escapeHtml(item.id)}">
        <div class="tory-vault-card-meta">
          <strong>${escapeHtml(item.title || "수집")}</strong>
          <span>${mode}</span>
          ${scene ? `<span>씬: ${scene}</span>` : ""}
          ${when ? `<span>${escapeHtml(when)}</span>` : ""}
        </div>
        <div class="tory-vault-card-body">${body}</div>
        <div class="tory-vault-card-actions">
          <button type="button" class="secondary" data-vault-copy="${escapeHtml(item.id)}">복사</button>
          <button type="button" class="secondary" data-vault-delete="${escapeHtml(item.id)}">삭제</button>
        </div>
      </article>`;
  }).join("");
}

function setupToryVault() {
  $("newToryVaultButton")?.addEventListener("click", () => {
    if (!state.projectId) return toast("먼저 작품을 선택해 주세요.");
    promptText({
      title: "수집창고 메모",
      message: "수집창고에 넣을 메모를 적어 주세요.",
      label: "메모",
      defaultValue: "",
      placeholder: "짧은 메모",
      maxlength: 2000,
      confirmLabel: "넣기",
    }).then((text) => {
      if (text === null) return;
      const body = text.trim();
      if (!body) return toast("내용이 비어 있어요.");
      collectToToryVault({ text: body, title: "직접 메모", mode: "note", prompt: "" });
      setActiveBinder("settings");
      state.openSettingsSection = "toryVault";
      applySettingsSectionState();
    }).catch(handleError);
  });
  $("clearToryVaultButton")?.addEventListener("click", () => {
    if (!state.projectId) return;
    if (!loadToryVault().length) return toast("비울 수집이 없어요.");
    if (!window.confirm("토리 수집창고를 모두 비울까요?")) return;
    saveToryVault([]);
    renderToryVaultList();
    renderSettingsCodex();
    toast("수집창고를 비웠어요.");
  });
  $("toryVaultList")?.addEventListener("click", (event) => {
    const copyId = event.target.closest?.("[data-vault-copy]")?.dataset?.vaultCopy;
    const delId = event.target.closest?.("[data-vault-delete]")?.dataset?.vaultDelete;
    if (copyId) {
      const item = loadToryVault().find((v) => v.id === copyId);
      if (!item?.body) return;
      navigator.clipboard?.writeText(item.body).then(
        () => toast("복사했어요."),
        () => {
          try {
            const ta = document.createElement("textarea");
            ta.value = item.body;
            document.body.appendChild(ta);
            ta.select();
            document.execCommand("copy");
            ta.remove();
            toast("복사했어요.");
          } catch (_) {
            toast("복사에 실패했어요.");
          }
        },
      );
      return;
    }
    if (delId) {
      if (!window.confirm("이 수집을 삭제할까요?")) return;
      saveToryVault(loadToryVault().filter((v) => v.id !== delId));
      renderToryVaultList();
      renderSettingsCodex();
      toast("삭제했어요.");
    }
  });
  renderToryVaultList();
}

function sourceStorageKey(projectId = state.projectId) {
  return `${SOURCE_STORAGE_PREFIX}${projectId || "0"}`;
}

function loadSources() {
  if (!state.projectId) return [];
  try {
    const raw = localStorage.getItem(sourceStorageKey());
    const arr = raw ? JSON.parse(raw) : [];
    return Array.isArray(arr) ? arr.filter((item) => item && item.id) : [];
  } catch (_) {
    return [];
  }
}

function saveSources(list) {
  if (!state.projectId) return;
  try {
    localStorage.setItem(sourceStorageKey(), JSON.stringify(list));
  } catch (_) {
    /* ignore */
  }
}

function normalizeSourceUrl(url) {
  const value = String(url || "").trim();
  if (!value) return "";
  if (/^https?:\/\//i.test(value)) return value;
  if (/^[\w.-]+\.[\w.-]+/.test(value)) return `https://${value}`;
  return value;
}

function sourceFileExt(name = "") {
  const m = String(name || "").toLowerCase().match(/(\.[a-z0-9]+)$/);
  return m ? m[1] : "";
}

function sourceFileKindLabel(ext = "") {
  const e = String(ext || "").toLowerCase();
  if (e === ".pdf") return "PDF";
  if (e === ".docx" || e === ".doc") return "Word";
  if (e === ".hwp" || e === ".hwpx") return "한글";
  if (e === ".txt" || e === ".text" || e === ".md" || e === ".markdown") return "텍스트";
  if (e === ".rtf") return "RTF";
  if (e === ".odt") return "ODT";
  return "파일";
}

function formatSourceFileSize(bytes) {
  const n = Number(bytes) || 0;
  if (n < 1024) return `${n} B`;
  if (n < 1024 * 1024) return `${(n / 1024).toFixed(1)} KB`;
  return `${(n / (1024 * 1024)).toFixed(1)} MB`;
}

function openSourceFilesDb() {
  return new Promise((resolve, reject) => {
    if (!window.indexedDB) {
      reject(new Error("이 브라우저는 파일 저장(IndexedDB)을 지원하지 않아요."));
      return;
    }
    const req = indexedDB.open(SOURCE_FILE_DB_NAME, 1);
    req.onupgradeneeded = () => {
      const db = req.result;
      if (!db.objectStoreNames.contains(SOURCE_FILE_STORE)) {
        db.createObjectStore(SOURCE_FILE_STORE);
      }
    };
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error || new Error("파일 저장소를 열지 못했어요."));
  });
}

function sourceFileDbKey(sourceId, projectId = state.projectId) {
  return `${projectId || 0}:${sourceId}`;
}

async function putSourceFileBlob(sourceId, record) {
  const db = await openSourceFilesDb();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(SOURCE_FILE_STORE, "readwrite");
    tx.objectStore(SOURCE_FILE_STORE).put(record, sourceFileDbKey(sourceId));
    tx.oncomplete = () => resolve(true);
    tx.onerror = () => reject(tx.error || new Error("파일 저장에 실패했어요."));
  });
}

async function getSourceFileBlob(sourceId) {
  const db = await openSourceFilesDb();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(SOURCE_FILE_STORE, "readonly");
    const req = tx.objectStore(SOURCE_FILE_STORE).get(sourceFileDbKey(sourceId));
    req.onsuccess = () => resolve(req.result || null);
    req.onerror = () => reject(req.error || new Error("파일을 읽지 못했어요."));
  });
}

async function deleteSourceFileBlob(sourceId) {
  try {
    const db = await openSourceFilesDb();
    return new Promise((resolve) => {
      const tx = db.transaction(SOURCE_FILE_STORE, "readwrite");
      tx.objectStore(SOURCE_FILE_STORE).delete(sourceFileDbKey(sourceId));
      tx.oncomplete = () => resolve(true);
      tx.onerror = () => resolve(false);
    });
  } catch (_) {
    return false;
  }
}

function fileToBase64(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => {
      const result = String(reader.result || "");
      const b64 = result.includes(",") ? result.split(",", 1)[1] : result;
      resolve(b64);
    };
    reader.onerror = () => reject(reader.error || new Error("파일을 읽지 못했어요."));
    reader.readAsDataURL(file);
  });
}

/** Inflate raw DEFLATE (zip method 8) via browser DecompressionStream. */
async function inflateRawDeflate(u8) {
  if (typeof DecompressionStream === "undefined") {
    throw new Error("이 브라우저는 DOCX 압축 해제를 지원하지 않아요.");
  }
  const stream = new Blob([u8]).stream().pipeThrough(new DecompressionStream("deflate-raw"));
  const ab = await new Response(stream).arrayBuffer();
  return new Uint8Array(ab);
}

/**
 * Minimal ZIP local-file scan (enough for DOCX word/document.xml).
 * @returns {Record<string, { method: number, data: Uint8Array }>}
 */
function scanZipLocalEntries(arrayBuffer) {
  const u8 = new Uint8Array(arrayBuffer);
  const out = {};
  let i = 0;
  while (i + 30 < u8.length) {
    // PK\x03\x04 local file header
    if (u8[i] !== 0x50 || u8[i + 1] !== 0x4b) {
      i += 1;
      continue;
    }
    if (u8[i + 2] === 0x01 && u8[i + 3] === 0x02) break; // central directory
    if (u8[i + 2] === 0x05 && u8[i + 3] === 0x06) break; // end of central
    if (!(u8[i + 2] === 0x03 && u8[i + 3] === 0x04)) {
      i += 1;
      continue;
    }
    const view = new DataView(arrayBuffer, i, Math.min(30, u8.length - i));
    const method = view.getUint16(8, true);
    const compSize = view.getUint32(18, true);
    const nameLen = view.getUint16(26, true);
    const extraLen = view.getUint16(28, true);
    const nameStart = i + 30;
    if (nameStart + nameLen > u8.length) break;
    const name = new TextDecoder("utf-8").decode(u8.subarray(nameStart, nameStart + nameLen));
    const dataStart = nameStart + nameLen + extraLen;
    const dataEnd = dataStart + compSize;
    if (dataEnd > u8.length) break;
    out[name] = { method, data: u8.subarray(dataStart, dataEnd) };
    i = dataEnd;
  }
  return out;
}

function docxXmlToPlainText(xml) {
  return String(xml || "")
    .replace(/<\/w:p>/gi, "\n")
    .replace(/<w:br\b[^>]*\/?>/gi, "\n")
    .replace(/<w:tab\b[^>]*\/?>/gi, "\t")
    .replace(/<[^>]+>/g, "")
    .replace(/&amp;/g, "&")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&quot;/g, "\"")
    .replace(/&apos;/g, "'")
    .replace(/&#(\d+);/g, (_, n) => {
      const code = Number(n);
      return Number.isFinite(code) ? String.fromCharCode(code) : "";
    })
    .replace(/&#x([0-9a-fA-F]+);/g, (_, n) => {
      const code = parseInt(n, 16);
      return Number.isFinite(code) ? String.fromCharCode(code) : "";
    })
    .replace(/[ \t]+\n/g, "\n")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
}

/** Client-side DOCX → plain text (no server). */
async function extractDocxTextClient(arrayBuffer) {
  const entries = scanZipLocalEntries(arrayBuffer);
  const entry = entries["word/document.xml"];
  if (!entry) throw new Error("DOCX 본문(document.xml)을 찾지 못했어요.");
  let xmlBytes;
  if (entry.method === 0) {
    xmlBytes = entry.data;
  } else if (entry.method === 8) {
    xmlBytes = await inflateRawDeflate(entry.data);
  } else {
    throw new Error(`지원하지 않는 DOCX 압축 방식입니다 (${entry.method}).`);
  }
  const xml = new TextDecoder("utf-8").decode(xmlBytes);
  const text = docxXmlToPlainText(xml);
  if (!text) throw new Error("DOCX에서 글자를 꺼내지 못했어요.");
  return text;
}

/**
 * Extract plain text for reference viewer.
 * DOCX: browser-first (works even if old server lacks /api/extract-text).
 * Other office formats: server /api/extract-text (+ alias).
 */
async function extractReferenceTextFromFile(file, arrayBuffer = null) {
  const name = file?.name || "upload.bin";
  const ext = sourceFileExt(name);
  const buf = arrayBuffer || (await file.arrayBuffer());

  // Client-side DOCX — avoids "알 수 없는 요청" when server is outdated
  if (ext === ".docx") {
    try {
      const text = await extractDocxTextClient(buf);
      return {
        filename: name,
        format: "docx",
        title: name.replace(/\.[^.]+$/, "") || "문서",
        text,
        viewer: "text",
        warnings: [],
      };
    } catch (clientErr) {
      // fall through to server
      console.warn("[supertory] client docx extract failed", clientErr);
    }
  }

  const b64 = await fileToBase64(file instanceof File ? file : new File([buf], name));
  const payload = JSON.stringify({
    filename: name,
    content_base64: b64,
  });
  try {
    return await api("/api/extract-text", { method: "POST", body: payload });
  } catch (error) {
    const msg = String(error?.message || error || "");
    // Alias path (same handler) — in case of path normalize differences
    if (/알 수 없는 요청|404|not found/i.test(msg)) {
      try {
        return await api("/api/reference/extract-text", { method: "POST", body: payload });
      } catch (error2) {
        const msg2 = String(error2?.message || error2 || "");
        if (/알 수 없는 요청|404|not found/i.test(msg2)) {
          throw new Error(
            "DOCX/한글 추출 API를 찾을 수 없습니다. SuperTORY 서버 창을 종료한 뒤 start_supertory.bat 으로 다시 실행해 주세요. (브라우저만 새로고침하면 예전 서버가 남을 수 있어요.)",
          );
        }
        throw error2;
      }
    }
    throw error;
  }
}

function revokeSplitSourceObjectUrl() {
  if (splitSourceObjectUrl) {
    try { URL.revokeObjectURL(splitSourceObjectUrl); } catch (_) { /* ignore */ }
    splitSourceObjectUrl = null;
  }
  const iframe = $("splitSourcePdf");
  if (iframe) iframe.removeAttribute("src");
}

function setSplitSourceUiMode(isSource) {
  const viewer = $("splitViewer");
  const sourceView = $("splitSourceViewer");
  const sceneBody = $("splitSceneBodyEditor");
  const titleInput = $("splitSceneTitleInput");
  const sceneSelect = $("splitSceneSelect");
  const editBtn = $("toggleSplitEditButton");
  const caption = viewer?.querySelector?.(".split-scene-caption");
  viewer?.classList.toggle("is-source-file", Boolean(isSource));
  sourceView?.classList.toggle("hidden", !isSource);
  if (sceneBody) {
    sceneBody.classList.toggle("hidden", Boolean(isSource));
    // Extra hard-hide so empty "이 씬의 원고가…" placeholder never steals height
    if (isSource) {
      sceneBody.setAttribute("hidden", "");
      sceneBody.style.display = "none";
      sceneBody.style.minHeight = "0";
      sceneBody.style.height = "0";
      sceneBody.style.flex = "none";
    } else {
      sceneBody.removeAttribute("hidden");
      sceneBody.style.removeProperty("display");
      sceneBody.style.removeProperty("min-height");
      sceneBody.style.removeProperty("height");
      sceneBody.style.removeProperty("flex");
    }
  }
  // Keep title bar visible for reference files — shows uploaded file name
  if (titleInput) {
    titleInput.classList.remove("hidden");
    titleInput.readOnly = Boolean(isSource) || !state.splitEditEnabled;
    titleInput.tabIndex = isSource ? -1 : (state.splitEditEnabled ? 0 : 0);
    if (isSource) {
      titleInput.placeholder = "자료 이름";
      titleInput.setAttribute("aria-label", "참고자료 이름");
    } else {
      titleInput.placeholder = "씬 제목";
      titleInput.setAttribute("aria-label", "분할 제목");
    }
  }
  // Keep companion picker available so users can switch between scenes and sources
  if (sceneSelect) {
    sceneSelect.disabled = false;
    sceneSelect.closest(".split-scene-label")?.classList.remove("hidden");
  }
  if (editBtn) {
    editBtn.classList.toggle("hidden", Boolean(isSource));
    if (isSource) {
      editBtn.disabled = true;
      editBtn.setAttribute("aria-pressed", "false");
    } else {
      editBtn.disabled = false;
    }
  }
  if (caption) caption.textContent = "분할 화면";
}

/** Display name for open reference file (prefer real file name). */
function getSplitSourceDisplayName(src) {
  if (!src) return "참고자료";
  const fileName = String(src.fileName || "").trim();
  const title = String(src.title || "").trim();
  // Prefer uploaded file name; fall back to saved title
  return fileName || title || "참고자료";
}

function renderSourceList() {
  const list = $("sourceList");
  if (!list) return;
  const sources = loadSources();
  if (!sources.length) {
    list.innerHTML = `<p class="hint source-empty">아직 자료가 없어요.<br>+ 자료로 링크 또는 파일을 추가해 보세요.</p>`;
    return;
  }
  list.innerHTML = sources.map((src) => {
    const title = escapeHtml(src.title || "제목 없음");
    const url = String(src.url || "").trim();
    const note = escapeHtml(src.note || "");
    const isFile = src.kind === "file" || Boolean(src.fileName);
    const ext = sourceFileExt(src.fileName || src.fileExt || "");
    const kindLabel = isFile ? sourceFileKindLabel(ext || src.fileExt) : "";
    const meta = isFile
      ? `<div class="source-card-meta"><span class="source-file-badge">${escapeHtml(kindLabel)}</span> ${escapeHtml(src.fileName || "")}${src.fileSize ? ` · ${escapeHtml(formatSourceFileSize(src.fileSize))}` : ""}</div>`
      : "";
    const urlHtml = url
      ? `<a class="source-card-url" href="${escapeHtml(url)}" target="_blank" rel="noopener noreferrer">${escapeHtml(url)}</a>`
      : "";
    const isPdf = isFile && (src.viewer === "pdf" || sourceFileExt(src.fileName || src.fileExt || "") === ".pdf");
    const openBtn = (isFile || url)
      ? `<button type="button" class="primary" data-source-open="${escapeHtml(src.id)}" title="${isFile ? "옆에 펼쳐 보기 · 단독 열람" : "링크 미리보기 · 단독 열람"}">${isFile ? "열기" : "링크 열기"}</button>`
      : "";
    const exportBtns = isFile && !isPdf
      ? `<button type="button" class="secondary" data-source-export-id="${escapeHtml(src.id)}" data-source-export-fmt="docx" title="Word로 내보내기">DOCX</button>
         <button type="button" class="secondary" data-source-export-id="${escapeHtml(src.id)}" data-source-export-fmt="hwpx" title="한글로 내보내기">HWPX</button>`
      : "";
    return `
      <article class="source-card ${isFile ? "is-file" : ""}" data-source-id="${escapeHtml(src.id)}">
        <div class="source-card-title">${title}</div>
        ${meta}
        ${urlHtml}
        ${note ? `<div class="source-card-note">${note}</div>` : ""}
        <div class="source-card-actions">
          ${openBtn}
          ${exportBtns}
          <button type="button" class="secondary" data-source-edit="${escapeHtml(src.id)}">수정</button>
          <button type="button" class="secondary" data-source-delete="${escapeHtml(src.id)}">삭제</button>
        </div>
      </article>`;
  }).join("");
}

function openSourceModal(options = {}) {
  const modal = $("sourceModal");
  if (!modal) return;
  pendingSourceFile = null;
  $("sourceEditId").value = options.id || "";
  $("sourceTitle").value = options.title || "";
  $("sourceUrl").value = options.url || "";
  $("sourceNote").value = options.note || "";
  if ($("sourceFileInput")) $("sourceFileInput").value = "";
  const current = $("sourceFileCurrent");
  if (current) {
    if (options.fileName) {
      current.textContent = `저장된 파일: ${options.fileName}${options.fileSize ? ` (${formatSourceFileSize(options.fileSize)})` : ""} · 새 파일을 고르면 교체됩니다`;
      current.classList.remove("hidden");
    } else {
      current.textContent = "";
      current.classList.add("hidden");
    }
  }
  $("sourceModalTitle").textContent = options.id ? "참고자료·출처 수정" : "참고자료·출처 추가";
  $("sourceSaveButton").textContent = options.id ? "저장" : "추가";
  modal.classList.remove("hidden");
  requestAnimationFrame(() => $("sourceTitle")?.focus());
}

function closeSourceModal() {
  $("sourceModal")?.classList.add("hidden");
  pendingSourceFile = null;
  if ($("sourceFileInput")) $("sourceFileInput").value = "";
}

async function saveSourceFromModal(event) {
  if (event) event.preventDefault();
  if (!state.projectId) return toast("먼저 작품을 선택해 주세요.");
  const title = ($("sourceTitle")?.value || "").trim();
  if (!title) return toast("자료 제목을 적어 주세요.");
  const url = normalizeSourceUrl($("sourceUrl")?.value || "");
  const note = ($("sourceNote")?.value || "").trim();
  const editId = ($("sourceEditId")?.value || "").trim();
  const file = pendingSourceFile || $("sourceFileInput")?.files?.[0] || null;
  const list = loadSources();
  const saveBtn = $("sourceSaveButton");
  if (saveBtn) {
    saveBtn.disabled = true;
    saveBtn.textContent = file ? "파일 처리 중…" : "저장 중…";
  }

  try {
    if (file) {
      const ext = sourceFileExt(file.name);
      if (!SOURCE_FILE_EXTS.has(ext)) {
        toast("지원 형식: PDF, DOCX, HWP/HWPX, TXT, MD, RTF, ODT");
        return;
      }
      if (file.size > SOURCE_FILE_MAX_BYTES) {
        toast(`파일이 너무 커요. ${SOURCE_FILE_MAX_BYTES / (1024 * 1024)}MB 이하만 올려 주세요.`);
        return;
      }
    }

    let fileMeta = null;
    let fileRecord = null;
    if (file) {
      const ext = sourceFileExt(file.name);
      const mime = file.type
        || (ext === ".pdf" ? "application/pdf"
          : ext === ".docx" ? "application/vnd.openxmlformats-officedocument.wordprocessingml.document"
            : "application/octet-stream");
      const buffer = await file.arrayBuffer();
      const blob = new Blob([buffer], { type: mime });
      let textContent = "";
      let viewer = ext === ".pdf" ? "pdf" : "text";
      let warnings = [];
      if (ext === ".pdf") {
        viewer = "pdf";
      } else if (ext === ".txt" || ext === ".text" || ext === ".md" || ext === ".markdown") {
        textContent = new TextDecoder("utf-8").decode(buffer);
        viewer = "text";
      } else if (ext === ".doc") {
        throw new Error("옛 Word(.doc)는 DOCX로 저장한 뒤 올려 주세요.");
      } else {
        const extracted = await extractReferenceTextFromFile(file, buffer);
        textContent = String(extracted.text || "");
        viewer = extracted.viewer === "pdf" ? "pdf" : "text";
        warnings = Array.isArray(extracted.warnings) ? extracted.warnings : [];
        if (!textContent && viewer === "text") {
          throw new Error(warnings[0] || "파일에서 글자를 꺼내지 못했어요.");
        }
      }
      fileMeta = {
        kind: "file",
        fileName: file.name,
        fileExt: ext,
        fileMime: mime,
        fileSize: file.size,
        viewer,
        warnings: warnings.slice(0, 4),
      };
      fileRecord = {
        blob,
        mime,
        fileName: file.name,
        textContent: textContent.slice(0, 200000),
        viewer,
        savedAt: Date.now(),
      };
    }

    if (editId) {
      const item = list.find((s) => s.id === editId);
      if (!item) return toast("수정할 자료를 찾지 못했어요.");
      item.title = title;
      item.url = url;
      item.note = note;
      if (fileMeta && fileRecord) {
        Object.assign(item, fileMeta);
        await putSourceFileBlob(item.id, fileRecord);
      }
      saveSources(list);
      closeSourceModal();
      renderSourceList();
      renderSettingsCodex();
      toast(fileMeta ? "참고자료 파일을 업데이트했어요." : "참고자료·출처를 수정했어요.");
      return;
    }

    const id = `src-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 6)}`;
    const item = {
      id,
      title,
      url,
      note,
      kind: fileMeta ? "file" : "link",
      createdAt: new Date().toISOString(),
      ...(fileMeta || {}),
    };
    if (fileRecord) await putSourceFileBlob(id, fileRecord);
    list.unshift(item);
    saveSources(list);
    closeSourceModal();
    setActiveBinder("settings");
    state.openSettingsSection = "sources";
    applySettingsSectionState();
    renderSourceList();
    renderSettingsCodex();
    toast(fileMeta
      ? "파일을 참고자료에 넣었어요. 「펼쳐 보기」로 작성 옆에 열어 보세요."
      : "참고자료·출처를 추가했어요.");
  } catch (error) {
    handleError(error);
  } finally {
    if (saveBtn) {
      saveBtn.disabled = false;
      saveBtn.textContent = editId ? "저장" : "추가";
    }
  }
}

function hideSplitSourceExportMenu() {
  $("splitSourceExportMenu")?.classList.add("hidden");
  $("splitSourceExportButton")?.setAttribute("aria-expanded", "false");
}

function getSplitSourcePlainText() {
  const textEl = $("splitSourceText");
  if (!textEl || textEl.classList.contains("hidden")) return "";
  return (textEl.innerText || textEl.textContent || "").replace(/\u00a0/g, " ");
}

function applySplitSourceEditUi() {
  const textEl = $("splitSourceText");
  const btn = $("splitSourceEditButton");
  const canEdit = splitSourceViewerMode === "text";
  const on = Boolean(canEdit && splitSourceEditEnabled);
  if (textEl) {
    textEl.setAttribute("contenteditable", on ? "true" : "false");
    textEl.spellcheck = on;
    textEl.classList.toggle("is-editing", on);
    textEl.setAttribute("aria-label", on ? "참고자료 본문 (편집 중)" : "참고자료 본문 (읽기 전용)");
    // Force normal-editor caret (CSS also overrides .split-body-editor transparent caret)
    textEl.style.outline = "none";
    textEl.style.boxShadow = "none";
    textEl.style.caretColor = on ? "var(--page-ink)" : "transparent";
  }
  $("splitViewer")?.classList.toggle("source-text-editing", on);
  if (btn) {
    btn.disabled = !canEdit;
    btn.classList.toggle("hidden", !canEdit);
    btn.classList.toggle("is-on", on);
    btn.setAttribute("aria-pressed", on ? "true" : "false");
    btn.textContent = on ? "편집 중" : "편집";
    btn.title = !canEdit
      ? (splitSourceViewerMode === "link"
        ? "링크는 미리보기 전용이에요. 새 탭에서 열어 보세요."
        : "PDF는 SuperTORY에서 글자 편집이 불가합니다")
      : on
        ? "편집 중 — 누르면 읽기 전용으로 돌아갑니다"
        : "텍스트로 불러온 참고자료를 SuperTORY에서 편집합니다";
  }
  $("splitSourceExportButton")?.classList.toggle("hidden", !canEdit && splitSourceViewerMode !== "text" && splitSourceViewerMode !== "pdf");
  // PDF / link: hide text export menu
  if (splitSourceViewerMode === "pdf" || splitSourceViewerMode === "link") {
    $("splitSourceExportButton")?.classList.add("hidden");
  } else if (splitSourceViewerMode === "text") {
    $("splitSourceExportButton")?.classList.remove("hidden");
  }
}

async function saveSplitSourceText({ quiet = false } = {}) {
  if (!state.splitSourceId || splitSourceViewerMode !== "text") return false;
  const text = getSplitSourcePlainText();
  let record = null;
  try {
    record = await getSourceFileBlob(state.splitSourceId);
  } catch (_) {
    record = null;
  }
  const src = loadSources().find((s) => s.id === state.splitSourceId);
  const nextRecord = {
    blob: record?.blob || null,
    mime: record?.mime || "text/plain",
    fileName: record?.fileName || src?.fileName || "note.txt",
    textContent: text.slice(0, 200000),
    viewer: "text",
    savedAt: Date.now(),
  };
  await putSourceFileBlob(state.splitSourceId, nextRecord);
  splitSourceDirty = false;
  if (!quiet) setSplitSaveStatus("참고자료 저장됨");
  else setSplitSaveStatus(splitSourceEditEnabled ? "참고자료 · 편집 중 · 저장됨" : "참고자료 · 저장됨");
  return true;
}

function markSplitSourceDirty() {
  if (!splitSourceEditEnabled || splitSourceViewerMode !== "text") return;
  splitSourceDirty = true;
  setSplitSaveStatus("참고자료 · 저장 대기 중…");
  if (splitSourceSaveTimer) window.clearTimeout(splitSourceSaveTimer);
  splitSourceSaveTimer = window.setTimeout(() => {
    saveSplitSourceText({ quiet: true }).catch(handleError);
  }, 800);
}

async function setSplitSourceEditEnabled(enabled, { silent = false } = {}) {
  if (splitSourceViewerMode !== "text") {
    if (!silent) toast("텍스트로 불러온 자료만 SuperTORY에서 편집할 수 있어요.");
    return;
  }
  if (splitSourceEditEnabled && !enabled && splitSourceDirty) {
    await saveSplitSourceText({ quiet: true });
  }
  splitSourceEditEnabled = Boolean(enabled);
  applySplitSourceEditUi();
  setSplitSaveStatus(
    splitSourceEditEnabled ? "참고자료 · 편집 중 (SuperTORY)" : "참고자료 · 읽기 전용",
  );
  if (!silent) {
    toast(splitSourceEditEnabled
      ? "참고자료 편집 모드예요. 수정 후 내보내기로 Word·한글 파일로 받을 수 있어요."
      : "참고자료 읽기 전용으로 전환했어요.");
  }
  if (splitSourceEditEnabled) {
    requestAnimationFrame(() => {
      const el = $("splitSourceText");
      if (!el) return;
      el.focus();
      // Place caret at end so typing works like the main editor
      try {
        const sel = window.getSelection();
        const range = document.createRange();
        range.selectNodeContents(el);
        range.collapse(false);
        sel?.removeAllRanges();
        sel?.addRange(range);
      } catch (_) { /* ignore */ }
    });
  }
}

/**
 * Download one reference document (not full manuscript).
 * format: docx | hwpx | txt | md | rtf | html
 */
async function exportReferencePlainText({ title, text, formatKey }) {
  const key = String(formatKey || "docx").toLowerCase();
  const body = {
    title: String(title || "참고자료").slice(0, 200),
    text: String(text || ""),
    format: key,
  };
  let response;
  try {
    response = await fetch("/api/export-text", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(body),
    });
  } catch (_) {
    throw new Error("내보내기 서버에 연결하지 못했어요. SuperTORY를 다시 실행해 주세요.");
  }
  if (!response.ok) {
    let message = "내보내기에 실패했습니다.";
    try {
      const err = await response.json();
      if (err?.error) message = err.error;
    } catch (_) { /* ignore */ }
    if (/알 수 없는 요청|404/i.test(message)) {
      message = "내보내기 API를 찾을 수 없습니다. SuperTORY 서버를 종료한 뒤 다시 실행해 주세요.";
    }
    throw new Error(message);
  }
  const blob = await response.blob();
  let filename = `${body.title}.${key === "hwpx" ? "hwpx" : key}`;
  const dispo = response.headers.get("Content-Disposition") || "";
  const m = dispo.match(/filename\*=UTF-8''([^;]+)|filename="([^"]+)"/i);
  if (m) {
    try {
      filename = decodeURIComponent(m[1] || m[2] || filename);
    } catch (_) { /* keep */ }
  }
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  a.remove();
  window.setTimeout(() => URL.revokeObjectURL(url), 2000);
  toast(`${filename} 내려받기를 시작했어요.`);
}

async function exportOpenSplitSource(formatKey) {
  if (state.splitKind !== "source" || !state.splitSourceId) {
    return toast("내보낼 참고자료가 열려 있지 않아요.");
  }
  if (splitSourceViewerMode !== "text") {
    return toast("텍스트로 불러온 자료만 Word·한글로 내보낼 수 있어요.");
  }
  if (splitSourceDirty || splitSourceEditEnabled) {
    await saveSplitSourceText({ quiet: true });
  }
  const src = loadSources().find((s) => s.id === state.splitSourceId);
  const title = src?.title || src?.fileName?.replace(/\.[^.]+$/, "") || "참고자료";
  const text = getSplitSourcePlainText();
  if (!text.trim()) return toast("내보낼 내용이 비어 있어요.");
  hideSplitSourceExportMenu();
  await exportReferencePlainText({ title, text, formatKey });
}

async function exportSourceById(sourceId, formatKey) {
  const src = loadSources().find((s) => s.id === sourceId);
  if (!src) return toast("자료를 찾지 못했어요.");
  // If this source is open and dirty, save first
  if (state.splitSourceId === sourceId && splitSourceViewerMode === "text") {
    if (splitSourceDirty || splitSourceEditEnabled) {
      await saveSplitSourceText({ quiet: true });
    }
    const text = getSplitSourcePlainText();
    const title = src.title || src.fileName?.replace(/\.[^.]+$/, "") || "참고자료";
    await exportReferencePlainText({ title, text, formatKey });
    return;
  }
  const record = await getSourceFileBlob(sourceId);
  if (!record) return toast("이 기기에 파일 본문이 없어요.");
  if ((record.viewer || src.viewer) === "pdf") {
    return toast("PDF는 SuperTORY 텍스트 내보내기 대상이 아니에요. 원본 PDF를 보관해 주세요.");
  }
  const text = String(record.textContent || "");
  if (!text.trim()) return toast("내보낼 글자가 없어요.");
  const title = src.title || src.fileName?.replace(/\.[^.]+$/, "") || "참고자료";
  await exportReferencePlainText({ title, text, formatKey });
}

async function openSourceFileInSplit(sourceId, mode = "split") {
  return openSourceInSplit(sourceId, mode);
}

/** Open a project reference (file or link) in the companion pane / popup. Manuscript optional. */
async function openSourceInSplit(sourceId, mode = "split") {
  if (!state.projectId) return toast("먼저 작품을 선택해 주세요.");
  const src = loadSources().find((s) => s.id === sourceId);
  if (!src) return toast("참고자료를 찾지 못했어요.");
  const hasFile = src.kind === "file" || Boolean(src.fileName);
  const url = String(src.url || "").trim();
  if (!hasFile && !url) return toast("열 수 있는 파일이나 링크가 없어요.");

  await flushSplitEdits();
  if (splitSourceDirty) {
    try { await saveSplitSourceText({ quiet: true }); } catch (_) { /* ignore */ }
  }
  revokeSplitSourceObjectUrl();
  const linkFrame = $("splitSourceLink");
  if (linkFrame) {
    linkFrame.src = "about:blank";
    linkFrame.classList.add("hidden");
  }
  splitSourceEditEnabled = false;
  splitSourceDirty = false;
  splitSourceViewerMode = "";
  hideSplitSourceExportMenu();

  // Without an open manuscript, use popup so the viewer can stand alone over welcome/settings.
  const standalone = !state.sceneId;
  const nextMode = standalone ? "popup" : (mode === "popup" ? "popup" : "split");
  state.splitEnabled = true;
  state.splitMode = nextMode;
  state.splitKind = "source";
  state.splitSourceId = sourceId;
  state.splitSceneId = null;
  state.splitScene = null;
  if (state.splitEditEnabled) setSplitEditEnabled(false, { silent: true });
  applySplitLayout();
  closeViewModeMenu();
  fillSplitCompanionSelect();
  await renderSplitSourceViewer();
  toast(standalone
    ? (hasFile ? "참고자료를 단독 창으로 열었어요." : "링크를 단독 창으로 열었어요.")
    : (state.splitMode === "popup"
      ? "참고자료를 팝업으로 열었어요."
      : "참고자료를 옆에 펼쳤어요."));
}

function fillSplitCompanionSelect() {
  const select = $("splitSceneSelect");
  if (!select) return;
  const scenes = allScenes().filter((scene) => scene.id !== state.sceneId);
  const sources = typeof loadSources === "function" ? loadSources() : [];
  const parts = [];
  if (scenes.length) {
    parts.push(`<optgroup label="회차">${scenes.map((scene) => {
      const selected = state.splitKind !== "source" && Number(scene.id) === Number(state.splitSceneId);
      const label = `${scene.chapterTitle || "폴더"} · ${scene.title || "회차"}`;
      return `<option value="scene:${scene.id}" ${selected ? "selected" : ""}>${escapeHtml(label)}</option>`;
    }).join("")}</optgroup>`);
  }
  if (sources.length) {
    parts.push(`<optgroup label="참고자료">${sources.map((src) => {
      const isFile = src.kind === "file" || Boolean(src.fileName);
      const url = String(src.url || "").trim();
      if (!isFile && !url) return "";
      const selected = state.splitKind === "source" && String(src.id) === String(state.splitSourceId);
      const tag = isFile ? "파일" : "링크";
      const label = getSplitSourceDisplayName(src);
      return `<option value="source:${escapeHtml(src.id)}" ${selected ? "selected" : ""}>[${tag}] ${escapeHtml(label)}</option>`;
    }).filter(Boolean).join("")}</optgroup>`);
  }
  if (!parts.length) {
    select.innerHTML = `<option value="">(함께볼 항목 없음)</option>`;
    return;
  }
  select.innerHTML = parts.join("");
  if (state.splitKind === "source" && state.splitSourceId) {
    select.value = `source:${state.splitSourceId}`;
  } else if (state.splitSceneId) {
    select.value = `scene:${state.splitSceneId}`;
  }
}

async function selectSplitCompanion() {
  const raw = String($("splitSceneSelect")?.value || "");
  if (!raw) return;
  if (raw.startsWith("source:")) {
    const id = raw.slice(7);
    if (state.splitKind === "source" && String(state.splitSourceId) === String(id)) return;
    await openSourceInSplit(id, state.splitMode || "split");
    return;
  }
  let nextId = 0;
  if (raw.startsWith("scene:")) nextId = Number(raw.slice(6));
  else nextId = Number(raw);
  if (!nextId || !Number.isFinite(nextId)) return;
  if (state.splitKind === "scene" && nextId === state.splitSceneId) return;
  await flushSplitEdits();
  if (splitSourceDirty) {
    try { await saveSplitSourceText({ quiet: true }); } catch (_) { /* ignore */ }
  }
  revokeSplitSourceObjectUrl();
  const linkFrame = $("splitSourceLink");
  if (linkFrame) {
    linkFrame.src = "about:blank";
    linkFrame.classList.add("hidden");
  }
  state.splitKind = "scene";
  state.splitSourceId = null;
  state.splitSceneId = nextId;
  splitSourceViewerMode = "";
  splitSourceEditEnabled = false;
  setSplitSourceUiMode(false);
  await renderSplitViewer();
}

async function selectSplitScene() {
  return selectSplitCompanion();
}

async function renderSplitSourceViewer() {
  if (!state.splitEnabled || state.splitKind !== "source") return;
  const src = loadSources().find((s) => s.id === state.splitSourceId);
  if (!src) {
    await closeSplitView();
    toast("참고자료를 찾지 못해 보기를 닫았어요.");
    return;
  }
  setSplitSourceUiMode(true);
  fillSplitCompanionSelect();
  updateSplitChrome();
  applySplitEditMode();

  const badge = $("splitSourceBadge");
  const nameEl = $("splitSourceFileName");
  const pdf = $("splitSourcePdf");
  const linkFrame = $("splitSourceLink");
  const textEl = $("splitSourceText");
  const msg = $("splitSourceMessage");
  const hasFile = src.kind === "file" || Boolean(src.fileName);
  const url = String(src.url || "").trim();
  const ext = sourceFileExt(src.fileName || src.fileExt || "");
  if (badge) badge.textContent = hasFile ? sourceFileKindLabel(ext) : "링크";
  if (nameEl) nameEl.textContent = getSplitSourceDisplayName(src);
  if (pdf) {
    pdf.classList.add("hidden");
    pdf.removeAttribute("src");
  }
  if (linkFrame) {
    linkFrame.classList.add("hidden");
    linkFrame.src = "about:blank";
  }
  if (textEl) {
    textEl.classList.add("hidden");
    textEl.innerHTML = "";
  }
  if (msg) {
    msg.classList.add("hidden");
    msg.textContent = "";
  }

  const applyTitle = (displayName) => {
    if (nameEl) nameEl.textContent = displayName;
    if ($("splitSceneTitleInput")) {
      const titleEl = $("splitSceneTitleInput");
      titleEl.classList.remove("hidden");
      titleEl.readOnly = true;
      titleEl.value = displayName;
      titleEl.title = displayName;
      titleEl.placeholder = "자료 이름";
    }
  };

  // URL-only reference: preview in iframe + external open fallback
  if (!hasFile && url) {
    splitSourceViewerMode = "link";
    splitSourceEditEnabled = false;
    applySplitSourceEditUi();
    if (linkFrame) {
      linkFrame.src = url;
      linkFrame.classList.remove("hidden");
    }
    if (msg) {
      msg.classList.remove("hidden");
      msg.innerHTML = `미리보기가 안 보이면 <a href="${escapeHtml(url)}" target="_blank" rel="noopener noreferrer">새 탭에서 열기</a>`;
    }
    setSplitSaveStatus("참고자료 · 링크 미리보기");
    applyTitle(getSplitSourceDisplayName(src));
    if (state.splitMode === "split") {
      requestAnimationFrame(() => layoutSplitPrimaryPane());
    }
    return;
  }

  let record = null;
  try {
    record = await getSourceFileBlob(src.id);
  } catch (error) {
    splitSourceViewerMode = "";
    applySplitSourceEditUi();
    if (msg) {
      msg.classList.remove("hidden");
      msg.textContent = "저장된 파일을 읽지 못했어요. 자료를 다시 업로드해 주세요.";
    }
    return;
  }
  if (!record) {
    splitSourceViewerMode = "";
    applySplitSourceEditUi();
    if (url) {
      splitSourceViewerMode = "link";
      if (linkFrame) {
        linkFrame.src = url;
        linkFrame.classList.remove("hidden");
      }
      if (msg) {
        msg.classList.remove("hidden");
        msg.innerHTML = `파일 본문이 없어 링크로 열어요. <a href="${escapeHtml(url)}" target="_blank" rel="noopener noreferrer">새 탭에서 열기</a>`;
      }
      setSplitSaveStatus("참고자료 · 링크 미리보기");
      applyTitle(getSplitSourceDisplayName(src));
      return;
    }
    if (msg) {
      msg.classList.remove("hidden");
      msg.textContent = "이 기기에 파일 본문이 없어요. 수정에서 파일을 다시 올려 주세요.";
    }
    return;
  }

  const viewer = record.viewer || src.viewer || (ext === ".pdf" ? "pdf" : "text");
  if (viewer === "pdf" && record.blob) {
    splitSourceViewerMode = "pdf";
    splitSourceEditEnabled = false;
    revokeSplitSourceObjectUrl();
    splitSourceObjectUrl = URL.createObjectURL(record.blob);
    if (pdf) {
      pdf.src = splitSourceObjectUrl;
      pdf.classList.remove("hidden");
    }
    setSplitSaveStatus("참고자료 · PDF 뷰어 (편집 불가)");
  } else {
    splitSourceViewerMode = "text";
    const plain = String(record.textContent || "");
    if (!plain.trim()) {
      if (msg) {
        msg.classList.remove("hidden");
        msg.textContent = (src.warnings && src.warnings[0])
          || "이 파일에서 표시할 글자를 찾지 못했어요.";
      }
      if (textEl) {
        textEl.innerHTML = "";
        textEl.classList.remove("hidden");
      }
    } else if (textEl) {
      textEl.innerHTML = escapeHtml(plain).replace(/\r\n|\r|\n/g, "<br>");
      textEl.classList.remove("hidden");
    }
    setSplitSaveStatus(
      splitSourceEditEnabled ? "참고자료 · 편집 중 (SuperTORY)" : "참고자료 · 읽기 전용 · 편집·내보내기 가능",
    );
  }

  applySplitSourceEditUi();
  applyTitle(getSplitSourceDisplayName(src));
  if (state.splitMode === "split") {
    requestAnimationFrame(() => layoutSplitPrimaryPane());
  }
}

function setupSplitSourceEditor() {
  if (setupSplitSourceEditor._bound) return;
  setupSplitSourceEditor._bound = true;

  $("splitSourceEditButton")?.addEventListener("click", () => {
    setSplitSourceEditEnabled(!splitSourceEditEnabled).catch(handleError);
  });
  $("splitSourceText")?.addEventListener("input", () => markSplitSourceDirty());
  $("splitSourceExportButton")?.addEventListener("click", (event) => {
    event.stopPropagation();
    if (splitSourceViewerMode !== "text") {
      toast("텍스트로 불러온 자료만 형식을 골라 내보낼 수 있어요.");
      return;
    }
    const menu = $("splitSourceExportMenu");
    if (!menu) return;
    const open = menu.classList.contains("hidden");
    hideSplitSourceExportMenu();
    if (open) {
      menu.classList.remove("hidden");
      $("splitSourceExportButton")?.setAttribute("aria-expanded", "true");
    }
  });
  $("splitSourceExportMenu")?.addEventListener("click", (event) => {
    const btn = event.target.closest?.("[data-source-export]");
    if (!btn) return;
    event.preventDefault();
    exportOpenSplitSource(btn.dataset.sourceExport).catch(handleError);
  });
  document.addEventListener("click", (event) => {
    if (!event.target.closest?.(".split-source-export-wrap")) {
      hideSplitSourceExportMenu();
    }
  });
}

function setupSourceCollection() {
  $("newSourceButton")?.addEventListener("click", () => openSourceModal({}));
  $("sourceForm")?.addEventListener("submit", (event) => {
    saveSourceFromModal(event).catch(handleError);
  });
  $("sourceFileInput")?.addEventListener("change", () => {
    const file = $("sourceFileInput")?.files?.[0] || null;
    pendingSourceFile = file;
    const current = $("sourceFileCurrent");
    if (!current) return;
    if (file) {
      current.textContent = `선택: ${file.name} (${formatSourceFileSize(file.size)})`;
      current.classList.remove("hidden");
      // Prefill title from filename when empty
      if (!($("sourceTitle")?.value || "").trim()) {
        const stem = String(file.name || "").replace(/\.[^.]+$/, "").trim();
        if (stem && $("sourceTitle")) $("sourceTitle").value = stem.slice(0, 200);
      }
    } else {
      current.textContent = "";
      current.classList.add("hidden");
    }
  });
  document.querySelectorAll("[data-close-source]").forEach((el) => {
    el.addEventListener("click", closeSourceModal);
  });
  $("sourceList")?.addEventListener("click", (event) => {
    const openBtn = event.target.closest?.("[data-source-open]");
    if (openBtn) {
      openSourceFileInSplit(openBtn.dataset.sourceOpen, "split").catch(handleError);
      return;
    }
    const exportBtn = event.target.closest?.("[data-source-export-id]");
    if (exportBtn) {
      exportSourceById(
        exportBtn.dataset.sourceExportId,
        exportBtn.dataset.sourceExportFmt || "docx",
      ).catch(handleError);
      return;
    }
    const editBtn = event.target.closest?.("[data-source-edit]");
    if (editBtn) {
      const item = loadSources().find((s) => s.id === editBtn.dataset.sourceEdit);
      if (item) openSourceModal(item);
      return;
    }
    const delBtn = event.target.closest?.("[data-source-delete]");
    if (delBtn) {
      const id = delBtn.dataset.sourceDelete;
      const list = loadSources();
      const item = list.find((s) => s.id === id);
      if (!item) return;
      if (!window.confirm(`「${item.title || "이 자료"}」을(를) 삭제할까요?`)) return;
      deleteSourceFileBlob(id).catch(() => {});
      if (state.splitSourceId === id) {
        closeSplitView().catch(handleError);
      }
      saveSources(list.filter((s) => s.id !== id));
      renderSourceList();
      renderSettingsCodex();
      toast("참고자료·출처를 삭제했어요.");
    }
  });
  document.addEventListener("keydown", (event) => {
    if (event.key === "Escape" && !$("sourceModal")?.classList.contains("hidden")) {
      closeSourceModal();
    }
  });
  renderSourceList();
  setupSplitSourceEditor();
}
let pendingBaitQuote = "";
/** @type {string|null} last project id whose baits are in state.baits */
let baitCacheProjectId = null;
/** Bait ids currently shown in the recovery popup (for snooze actions). */
let baitNotifyActiveSceneId = null;
let baitNotifyActiveBaitIds = [];

function baitStorageKey(projectId = state.projectId) {
  return `${BAIT_STORAGE_PREFIX}${projectId || "0"}`;
}

function baitMigratedBackupKey(projectId = state.projectId) {
  return `${BAIT_STORAGE_PREFIX}migrated.${projectId || "0"}`;
}

/** Synchronous read of the in-memory DB cache (after refreshBaitsFromServer). */
function loadBaits() {
  if (!state.projectId) return [];
  if (baitCacheProjectId != null && Number(baitCacheProjectId) !== Number(state.projectId)) {
    return [];
  }
  const list = Array.isArray(state.baits) ? state.baits : [];
  return list.filter((item) => item && item.id).map((item) => normalizeBaitItem(item));
}

function setBaitCache(list, projectId = state.projectId) {
  const normalized = (Array.isArray(list) ? list : [])
    .filter((item) => item && item.id)
    .map((item) => normalizeBaitItem(item));
  state.baits = normalized;
  baitCacheProjectId = projectId != null ? Number(projectId) : null;
  // Keep binder icons + notify center in sync
  if (typeof renderOutline === "function" && Array.isArray(state.outline) && state.outline.length) {
    renderOutline(state.outline);
  }
  if (typeof renderToryNotifyList === "function") renderToryNotifyList();
}

/** @deprecated Prefer create/update/delete APIs. Kept for rare full-list rewrite paths. */
function saveBaits(list) {
  setBaitCache(list, state.projectId);
}

function readLocalBaitsRaw(projectId) {
  try {
    const raw = localStorage.getItem(baitStorageKey(projectId));
    if (!raw) return null;
    const arr = JSON.parse(raw);
    return Array.isArray(arr) ? arr : null;
  } catch (_) {
    return null;
  }
}

/**
 * One-shot: if this browser still has localStorage baits for the project,
 * upsert them into SQLite then move the key to a backup.
 */
async function migrateLocalBaitsToDb(projectId) {
  const pid = Number(projectId);
  if (!pid) return { migrated: false, count: 0 };
  const localItems = readLocalBaitsRaw(pid);
  if (!localItems || !localItems.length) {
    // Empty array still counts as "handled" — drop the key so we don't re-read.
    try {
      if (localStorage.getItem(baitStorageKey(pid)) != null) {
        localStorage.removeItem(baitStorageKey(pid));
      }
    } catch (_) { /* ignore */ }
    return { migrated: false, count: 0 };
  }
  const payloadItems = localItems
    .filter((item) => item && (item.id || item.quote || item.summary))
    .map((item) => {
      const n = normalizeBaitItem(item);
      return {
        id: n.id,
        kind: n.kind,
        quote: n.quote || n.summary || "(내용 없음)",
        summary: n.summary || "",
        recover_content: n.recoverContent || "",
        recover_at: n.recoverAt || "",
        recover_scene_id: n.recoverSceneId,
        plant_scene_id: n.plantSceneId,
        source_scene_id: n.sourceSceneId || n.plantSceneId,
        plant_at_note: n.plantAtNote || "",
        source_title: n.sourceTitle || "",
        notify_on_recover: n.notifyOnRecover !== false,
        snooze_until: n.snoozeUntil || null,
        created_at: n.createdAt || null,
      };
    });
  if (!payloadItems.length) {
    try { localStorage.removeItem(baitStorageKey(pid)); } catch (_) { /* ignore */ }
    return { migrated: false, count: 0 };
  }
  const result = await api(`/api/projects/${pid}/baits/import`, {
    method: "POST",
    body: JSON.stringify({ items: payloadItems }),
  });
  // Backup then remove primary key so data is not lost if import is partial.
  try {
    const raw = localStorage.getItem(baitStorageKey(pid));
    if (raw != null) {
      localStorage.setItem(baitMigratedBackupKey(pid), raw);
      localStorage.removeItem(baitStorageKey(pid));
    }
  } catch (_) { /* ignore */ }
  return {
    migrated: true,
    count: Number(result?.total || payloadItems.length) || payloadItems.length,
  };
}

async function refreshBaitsFromServer(projectId = state.projectId) {
  const pid = Number(projectId);
  if (!pid) {
    setBaitCache([], null);
    return [];
  }
  try {
    await migrateLocalBaitsToDb(pid);
  } catch (err) {
    console.warn("localStorage 떡밥 마이그레이션 실패 — 서버 목록만 불러옵니다.", err);
  }
  if (Number(state.projectId) !== pid) return loadBaits();
  const list = await api(`/api/projects/${pid}/baits`);
  if (Number(state.projectId) !== pid) return loadBaits();
  setBaitCache(list, pid);
  return loadBaits();
}

function baitToApiBody(item) {
  const n = normalizeBaitItem(item || {});
  return {
    id: n.id || undefined,
    kind: n.kind === "idea" ? "idea" : "plant",
    quote: n.quote || "",
    summary: n.summary || "",
    recover_content: n.recoverContent || "",
    recover_at: n.recoverAt || "",
    recover_scene_id: n.recoverSceneId,
    plant_scene_id: n.plantSceneId,
    source_scene_id: n.sourceSceneId || n.plantSceneId,
    plant_at_note: n.plantAtNote || "",
    source_title: n.sourceTitle || "",
    notify_on_recover: n.notifyOnRecover !== false,
    snooze_until: n.snoozeUntil || null,
    created_at: n.createdAt || undefined,
  };
}

async function createBaitOnServer(item) {
  if (!state.projectId) throw new Error("작품을 먼저 선택해 주세요.");
  const created = await api(`/api/projects/${state.projectId}/baits`, {
    method: "POST",
    body: JSON.stringify(baitToApiBody(item)),
  });
  const next = [normalizeBaitItem(created), ...loadBaits().filter((b) => b.id !== created.id)];
  setBaitCache(next, state.projectId);
  return normalizeBaitItem(created);
}

async function updateBaitOnServer(baitId, patch) {
  const id = String(baitId || "").trim();
  if (!id) throw new Error("떡밥 id가 없어요.");
  const updated = await api(`/api/baits/${encodeURIComponent(id)}`, {
    method: "PUT",
    body: JSON.stringify(baitToApiBody({ id, ...patch })),
  });
  const list = loadBaits();
  const idx = list.findIndex((b) => b.id === id);
  if (idx >= 0) list[idx] = normalizeBaitItem(updated);
  else list.unshift(normalizeBaitItem(updated));
  setBaitCache(list, state.projectId);
  return normalizeBaitItem(updated);
}

async function deleteBaitOnServer(baitId) {
  const id = String(baitId || "").trim();
  if (!id) return;
  await api(`/api/baits/${encodeURIComponent(id)}`, { method: "DELETE" });
  setBaitCache(loadBaits().filter((b) => b.id !== id), state.projectId);
}

/** Normalize legacy / API bait records to the richer camelCase shape. */
function normalizeBaitItem(raw) {
  const item = { ...(raw || {}) };
  // Accept snake_case from API.
  if (item.recover_content != null && item.recoverContent == null) item.recoverContent = item.recover_content;
  if (item.recover_at != null && item.recoverAt == null) item.recoverAt = item.recover_at;
  if (item.recover_scene_id != null && item.recoverSceneId == null) item.recoverSceneId = item.recover_scene_id;
  if (item.plant_scene_id != null && item.plantSceneId == null) item.plantSceneId = item.plant_scene_id;
  if (item.source_scene_id != null && item.sourceSceneId == null) item.sourceSceneId = item.source_scene_id;
  if (item.plant_at_note != null && item.plantAtNote == null) item.plantAtNote = item.plant_at_note;
  if (item.source_title != null && item.sourceTitle == null) item.sourceTitle = item.source_title;
  if (item.notify_on_recover != null && item.notifyOnRecover == null) item.notifyOnRecover = item.notify_on_recover;
  if (item.snooze_until != null && item.snoozeUntil == null) item.snoozeUntil = item.snooze_until;
  if (item.created_at != null && item.createdAt == null) item.createdAt = item.created_at;

  // plant = from manuscript; idea = pre-writing plan from settings
  if (item.kind !== "idea" && item.kind !== "plant") {
    item.kind = item.quote || item.sourceSceneId || item.plantSceneId ? "plant" : "idea";
  }
  // sourceSceneId is where the bait sentence lives (icon anchor — not episode order)
  if (item.sourceSceneId == null && item.plantSceneId != null) {
    item.sourceSceneId = item.plantSceneId;
  }
  item.plantSceneId = item.plantSceneId != null && item.plantSceneId !== ""
    ? Number(item.plantSceneId) || null
    : (item.sourceSceneId != null && item.sourceSceneId !== ""
      ? Number(item.sourceSceneId) || null
      : null);
  item.sourceSceneId = item.plantSceneId;
  item.recoverSceneId = item.recoverSceneId != null && item.recoverSceneId !== ""
    ? Number(item.recoverSceneId) || null
    : null;
  item.notifyOnRecover = item.notifyOnRecover !== false && item.notifyOnRecover !== 0
    && item.notifyOnRecover !== "0" && item.notifyOnRecover !== "false";
  item.recoverContent = item.recoverContent || item.ideaRecover || "";
  item.plantAtNote = item.plantAtNote || "";
  item.recoverAt = item.recoverAt || "";
  item.summary = item.summary || "";
  item.quote = item.quote || item.throwContent || item.ideaThrow || "";
  item.snoozeUntil = item.snoozeUntil || null;
  if (item.snoozeUntil === "") item.snoozeUntil = null;
  return item;
}

/** True when a bait recovery popup should be suppressed for this open. */
function isBaitSnoozedNow(bait, sceneId, nowMs = Date.now()) {
  const until = bait?.snoozeUntil;
  if (!until) return false;
  if (until === "next_open") {
    // Suppress while still on (or re-opening without having left) the recovery scene.
    return Number(bait.recoverSceneId) === Number(sceneId);
  }
  const ts = Date.parse(String(until));
  if (!Number.isFinite(ts)) return false;
  return nowMs < ts;
}

/** Scene ids that have planted bait text (yellow 떡).
 *  Only manuscript plants (drag → 떡밥 던지기), keyed by stored plantSceneId.
 *  Idea “예상 회차” does not get a yellow badge — no planted sentence yet.
 *  Reordering/shifting episodes does not move the badge (scene id, not order). */
function getBaitPlantSceneIds() {
  const ids = new Set();
  for (const bait of loadBaits()) {
    if (bait.kind === "idea") continue;
    const id = Number(bait.plantSceneId || bait.sourceSceneId);
    if (id > 0) ids.add(id);
  }
  return ids;
}

/** Scene ids scheduled for recovery (red 떡) — plant or idea, by recoverSceneId. */
function getBaitRecoverSceneIds() {
  const ids = new Set();
  for (const bait of loadBaits()) {
    const id = Number(bait.recoverSceneId);
    if (id > 0) ids.add(id);
  }
  return ids;
}

function fillBaitSceneSelects(selectedPlant = "", selectedRecover = "") {
  const optionsHtml = (() => {
    const scenes = typeof allScenes === "function" ? allScenes() : [];
    if (!scenes.length) {
      return `<option value="">(회차가 없어요)</option>`;
    }
    return [`<option value="">(미정)</option>`]
      .concat(scenes.map((scene) => {
        const id = Number(scene.id);
        const label = escapeHtml(scene.title || `씬 #${id}`);
        const chapter = scene.chapterTitle ? `${escapeHtml(scene.chapterTitle)} · ` : "";
        return `<option value="${id}">${chapter}${label}</option>`;
      }))
      .join("");
  })();
  const plantSel = $("baitPlantSceneSelect");
  const recoverSel = $("baitRecoverSceneSelect");
  if (plantSel) {
    plantSel.innerHTML = optionsHtml;
    if (selectedPlant) plantSel.value = String(selectedPlant);
  }
  if (recoverSel) {
    recoverSel.innerHTML = optionsHtml;
    if (selectedRecover) recoverSel.value = String(selectedRecover);
  }
}

function setBaitModalMode(mode) {
  const isIdea = mode === "idea";
  if ($("baitMode")) $("baitMode").value = isIdea ? "idea" : "plant";
  $("baitPlantFields")?.classList.toggle("hidden", isIdea);
  $("baitIdeaFields")?.classList.toggle("hidden", !isIdea);
  if ($("baitModalHint")) {
    $("baitModalHint").innerHTML = isIdea
      ? "본문 작성 전 <strong>아이디어 떡밥</strong>을 적어 둡니다. 던지기·회수 내용과 예상 회차를 저장하세요."
      : "본문에서 잡은 문장이 설정집 <strong>떡밥모음</strong>에 들어갑니다. 회수 예정 회차와 알림을 설정하세요.";
  }
  if ($("baitModalTitle")) {
    // keep title from openBaitModal
  }
  // plant mode: quote required; idea mode: throw content required
  if ($("baitQuote")) $("baitQuote").required = !isIdea;
}

function settingsOrderKey(projectId = state.projectId) {
  return `${SETTINGS_ORDER_PREFIX}${projectId || "0"}`;
}

function loadSettingsOrder() {
  try {
    const raw = localStorage.getItem(settingsOrderKey());
    const arr = raw ? JSON.parse(raw) : null;
    if (!Array.isArray(arr) || !arr.length) return [...DEFAULT_SETTINGS_ORDER];
    // Migrate old section keys → intro / logsyn
    const mapped = [];
    let sawLogsyn = false;
    for (const key of arr) {
      if (key === "synopsis" || key === "logline") {
        if (!sawLogsyn) {
          mapped.push("logsyn");
          sawLogsyn = true;
        }
        continue;
      }
      mapped.push(key);
    }
    // Keep known sections, append any missing defaults.
    const known = new Set(DEFAULT_SETTINGS_ORDER);
    let ordered = mapped.filter((key) => known.has(key));
    for (const key of DEFAULT_SETTINGS_ORDER) {
      if (!ordered.includes(key)) ordered.push(key);
    }
    // Snap exact previous factory defaults to the current default (keeps custom drag order).
    for (const legacy of LEGACY_SETTINGS_ORDERS) {
      if (
        ordered.length === legacy.length
        && legacy.every((key, i) => ordered[i] === key)
      ) {
        ordered = [...DEFAULT_SETTINGS_ORDER];
        break;
      }
    }
    // Prefer 토리 수집창고 between characters and sources when it was only appended last.
    const vaultAt = ordered.indexOf("toryVault");
    const charsAt = ordered.indexOf("characters");
    const sourcesAt = ordered.indexOf("sources");
    if (vaultAt >= 0 && charsAt >= 0 && sourcesAt >= 0) {
      const between = vaultAt > charsAt && vaultAt < sourcesAt;
      // Old default put vault after sources (or at end) — snap once to characters → vault → sources.
      if (!between && vaultAt > sourcesAt) {
        ordered.splice(vaultAt, 1);
        const insertAt = ordered.indexOf("characters") + 1;
        ordered.splice(insertAt, 0, "toryVault");
      }
    }
    // Prefer 흥행작 프로파일 연결 right after 떡밥모음 when newly appended at end.
    const successAt = ordered.indexOf("successProfile");
    const baitsAt = ordered.indexOf("baits");
    if (successAt >= 0 && baitsAt >= 0 && successAt !== baitsAt + 1 && successAt === ordered.length - 1) {
      ordered.splice(successAt, 1);
      ordered.splice(ordered.indexOf("baits") + 1, 0, "successProfile");
    }
    return ordered;
  } catch (_) {
    return [...DEFAULT_SETTINGS_ORDER];
  }
}

function saveSettingsOrder(order) {
  try {
    localStorage.setItem(settingsOrderKey(state.projectId || 0), JSON.stringify(order));
  } catch (_) {
    /* ignore */
  }
}

function applySettingsSectionOrder() {
  const accordion = $("settingsAccordion");
  if (!accordion) return;
  const order = loadSettingsOrder();
  order.forEach((key) => {
    const box = accordion.querySelector(`.settings-box[data-settings-section="${key}"]`);
    if (box) accordion.appendChild(box);
  });
}

function setupSettingsSectionDrag() {
  const accordion = $("settingsAccordion");
  if (!accordion || accordion.dataset.orderDragBound === "1") return;
  accordion.dataset.orderDragBound = "1";
  let dragged = null;
  let dragEnabledBox = null;

  const clear = () => {
    accordion.querySelectorAll(".settings-box").forEach((box) => {
      box.classList.remove("is-dragging", "drag-over-before", "drag-over-after");
      // Keep HTML5 drag disabled until grip is used (avoids accidental text drags).
      box.setAttribute("draggable", "false");
    });
    dragEnabledBox = null;
  };

  const boxes = () => [...accordion.querySelectorAll(".settings-box[data-settings-section]")];

  // Default: section not draggable; grip enables drag for this pointer sequence.
  boxes().forEach((box) => box.setAttribute("draggable", "false"));

  accordion.addEventListener("pointerdown", (event) => {
    const handle = event.target.closest?.(".settings-drag-handle");
    if (!handle || !accordion.contains(handle)) return;
    const box = handle.closest(".settings-box");
    if (!box) return;
    // Grip is outside the toggle button so HTML5 drag can start reliably.
    event.stopPropagation();
    boxes().forEach((el) => el.setAttribute("draggable", el === box ? "true" : "false"));
    dragEnabledBox = box;
  });

  // If user pressed grip but didn't drag, disable again.
  document.addEventListener("pointerup", () => {
    if (!dragged && dragEnabledBox) {
      dragEnabledBox.setAttribute("draggable", "false");
      dragEnabledBox = null;
    }
  });

  accordion.addEventListener("dragstart", (event) => {
    const box = event.target.closest?.(".settings-box");
    if (!box || !accordion.contains(box)) return;
    // Only when grip armed this box.
    if (dragEnabledBox !== box && !event.target.closest?.(".settings-drag-handle")) {
      event.preventDefault();
      return;
    }
    dragged = box;
    box.classList.add("is-dragging");
    try {
      event.dataTransfer.effectAllowed = "move";
      event.dataTransfer.setData("text/plain", box.dataset.settingsSection || "settings");
    } catch (_) {
      /* ignore */
    }
  });

  accordion.addEventListener("dragend", () => {
    dragged = null;
    clear();
  });

  accordion.addEventListener("dragover", (event) => {
    if (!dragged) return;
    event.preventDefault();
    try { event.dataTransfer.dropEffect = "move"; } catch (_) { /* ignore */ }
    const box = event.target.closest?.(".settings-box");
    if (!box || box === dragged || !accordion.contains(box)) return;
    const rect = box.getBoundingClientRect();
    const before = event.clientY < rect.top + rect.height / 2;
    boxes().forEach((other) => {
      other.classList.toggle("drag-over-before", other === box && before);
      other.classList.toggle("drag-over-after", other === box && !before);
    });
  });

  accordion.addEventListener("drop", (event) => {
    event.preventDefault();
    event.stopPropagation();
    if (!dragged) {
      clear();
      return;
    }
    const box = event.target.closest?.(".settings-box");
    if (box && box !== dragged && accordion.contains(box)) {
      const rect = box.getBoundingClientRect();
      const before = event.clientY < rect.top + rect.height / 2;
      if (before) accordion.insertBefore(dragged, box);
      else accordion.insertBefore(dragged, box.nextSibling);
    }
    const order = boxes()
      .map((el) => el.dataset.settingsSection)
      .filter(Boolean);
    if (order.length) {
      saveSettingsOrder(order);
      // Persist even when no project is selected (fallback key "0").
      if (!state.projectId) {
        try {
          localStorage.setItem(`${SETTINGS_ORDER_PREFIX}0`, JSON.stringify(order));
        } catch (_) {
          /* ignore */
        }
      }
      toast("설정집 폴더 순서를 바꿨어요.");
    }
    dragged = null;
    clear();
  });

  // Header click to expand must not fight with grip (grip is no longer inside toggle).
  accordion.querySelectorAll(".settings-box-header").forEach((header) => {
    header.addEventListener("click", (event) => {
      if (event.target.closest?.(".settings-drag-handle")) {
        event.preventDefault();
        event.stopPropagation();
      }
    }, true);
  });
}

function sceneTitleById(sceneId) {
  const id = Number(sceneId);
  if (!id) return "";
  for (const chapter of state.outline || []) {
    let found = "";
    walkSceneTree(chapter.scenes || [], (scene) => {
      if (Number(scene.id) === id) found = scene.title || `씬 #${id}`;
    });
    if (found) return found;
  }
  return "";
}

function renderBaitList() {
  const list = $("baitList");
  if (!list) return;
  const baits = loadBaits();
  if (!baits.length) {
    list.innerHTML = `<p class="hint bait-empty">아직 떡밥이 없어요.</p>`;
    return;
  }
  list.innerHTML = baits.map((bait) => {
    const kind = bait.kind === "idea" ? "idea" : "plant";
    const quote = escapeHtml(bait.quote || "");
    const summary = escapeHtml(bait.summary || "");
    const recoverContent = escapeHtml(bait.recoverContent || "");
    const plantTitle = bait.plantSceneId
      ? escapeHtml(sceneTitleById(bait.plantSceneId) || bait.sourceTitle || `씬 #${bait.plantSceneId}`)
      : escapeHtml(bait.plantAtNote || bait.sourceTitle || "(심은 회차 미정)");
    const recoverTitle = bait.recoverSceneId
      ? escapeHtml(sceneTitleById(bait.recoverSceneId) || `씬 #${bait.recoverSceneId}`)
      : escapeHtml(bait.recoverAt || "(회수 예정 미정)");
    const notify = bait.notifyOnRecover !== false;
    const kindLabel = kind === "idea" ? "아이디어" : "본문 심기";
    return `
      <article class="bait-card bait-kind-${kind}" data-bait-id="${escapeHtml(bait.id)}">
        <div class="bait-card-kind">${kindLabel}${notify && bait.recoverSceneId ? " · 알림 켜짐" : ""}</div>
        <div class="bait-card-quote">${quote || "(내용 없음)"}</div>
        <div class="bait-card-meta">
          ${summary ? `<div><strong>간략</strong> ${summary}</div>` : ""}
          ${recoverContent ? `<div><strong>회수 내용</strong> ${recoverContent}</div>` : ""}
          <div><strong>심은/예상 회차</strong> ${plantTitle}</div>
          <div><strong>회수 예정</strong> ${recoverTitle}</div>
        </div>
        <div class="bait-card-actions">
          <button type="button" class="secondary" data-bait-edit="${escapeHtml(bait.id)}">수정</button>
          <button type="button" class="secondary" data-bait-delete="${escapeHtml(bait.id)}">삭제</button>
        </div>
      </article>`;
  }).join("");
}

function openBaitModal(options = {}) {
  const modal = $("baitModal");
  if (!modal) return;
  const mode = options.kind === "idea" || options.mode === "idea" ? "idea" : "plant";
  $("baitEditId").value = options.id || "";
  setBaitModalMode(mode);
  fillBaitSceneSelects(
    options.plantSceneId || options.sourceSceneId || "",
    options.recoverSceneId || "",
  );
  if ($("baitQuote")) $("baitQuote").value = options.quote || "";
  if ($("baitSummary")) $("baitSummary").value = options.summary || "";
  if ($("baitIdeaThrow")) {
    $("baitIdeaThrow").value = options.quote || options.throwContent || options.ideaThrow || "";
  }
  if ($("baitIdeaRecover")) $("baitIdeaRecover").value = options.recoverContent || "";
  if ($("baitPlantAtNote")) $("baitPlantAtNote").value = options.plantAtNote || "";
  if ($("baitRecoverAt")) $("baitRecoverAt").value = options.recoverAt || "";
  if ($("baitNotifyOnRecover")) {
    $("baitNotifyOnRecover").checked = options.notifyOnRecover !== false;
  }
  $("baitNotifyRow")?.classList.remove("hidden");
  if (options.id) {
    if ($("baitModalTitle")) $("baitModalTitle").textContent = mode === "idea" ? "아이디어 떡밥 수정" : "떡밥 수정";
    if ($("baitSaveButton")) $("baitSaveButton").textContent = "저장";
  } else {
    if ($("baitModalTitle")) $("baitModalTitle").textContent = mode === "idea" ? "아이디어 떡밥" : "떡밥 던지기";
    if ($("baitSaveButton")) $("baitSaveButton").textContent = "떡밥모음에 넣기";
  }
  modal.classList.remove("hidden");
  requestAnimationFrame(() => {
    if (mode === "idea") ($("baitIdeaThrow") || $("baitSummary"))?.focus();
    else ($("baitSummary") || $("baitQuote"))?.focus();
  });
}

function closeBaitModal() {
  $("baitModal")?.classList.add("hidden");
  pendingBaitQuote = "";
}

async function saveBaitFromModal(event) {
  if (event) event.preventDefault();
  if (!state.projectId) return toast("먼저 작품을 선택해 주세요.");
  const mode = ($("baitMode")?.value || "plant") === "idea" ? "idea" : "plant";
  const editId = ($("baitEditId")?.value || "").trim();
  const summary = ($("baitSummary")?.value || "").trim();
  const recoverAt = ($("baitRecoverAt")?.value || "").trim();
  const recoverSceneId = Number($("baitRecoverSceneSelect")?.value || 0) || null;
  const plantSceneIdRaw = Number($("baitPlantSceneSelect")?.value || 0) || null;
  const plantAtNote = ($("baitPlantAtNote")?.value || "").trim();
  const notifyOnRecover = Boolean($("baitNotifyOnRecover")?.checked);
  const list = loadBaits();

  let quote = "";
  let recoverContent = "";
  let plantSceneId = null;
  let sourceTitle = "";

  if (mode === "idea") {
    quote = ($("baitIdeaThrow")?.value || "").trim();
    recoverContent = ($("baitIdeaRecover")?.value || "").trim();
    if (!quote) return toast("떡밥 던지기 내용을 적어 주세요.");
    plantSceneId = plantSceneIdRaw;
    sourceTitle = plantSceneId ? sceneTitleById(plantSceneId) : plantAtNote;
  } else {
    quote = ($("baitQuote")?.value || "").trim();
    if (!quote) return toast("떡밥 문장을 적어 주세요.");
    if (editId) {
      const prev = list.find((b) => b.id === editId);
      plantSceneId = prev?.plantSceneId || prev?.sourceSceneId || state.sceneId || null;
    } else {
      plantSceneId = state.sceneId || null;
    }
    sourceTitle = state.scene?.title || $("sceneTitle")?.value || sceneTitleById(plantSceneId) || "";
  }

  const saveBtn = $("baitSaveButton");
  if (saveBtn) saveBtn.disabled = true;
  try {
    if (editId) {
      const item = list.find((b) => b.id === editId);
      if (!item) return toast("수정할 떡밥을 찾지 못했어요.");
      await updateBaitOnServer(editId, {
        ...item,
        kind: mode,
        quote,
        summary,
        recoverContent,
        recoverAt,
        recoverSceneId,
        plantSceneId: plantSceneId ? Number(plantSceneId) : null,
        sourceSceneId: plantSceneId ? Number(plantSceneId) : null,
        plantAtNote,
        sourceTitle: sourceTitle || item.sourceTitle || "",
        notifyOnRecover,
      });
      closeBaitModal();
      renderBaitList();
      renderSettingsCodex();
      toast("떡밥을 수정했어요.");
      return;
    }

    await createBaitOnServer({
      kind: mode,
      quote,
      summary,
      recoverContent,
      recoverAt,
      recoverSceneId,
      plantSceneId: plantSceneId ? Number(plantSceneId) : null,
      sourceSceneId: plantSceneId ? Number(plantSceneId) : null,
      plantAtNote,
      sourceTitle: sourceTitle || "",
      notifyOnRecover,
      snoozeUntil: null,
    });
    closeBaitModal();
    setActiveBinder("settings");
    state.openSettingsSection = "baits";
    applySettingsSectionState();
    renderBaitList();
    renderSettingsCodex();
    toast(mode === "idea" ? "아이디어 떡밥을 저장했어요." : "떡밥모음에 넣었어요.");
  } catch (error) {
    handleError(error);
  } finally {
    if (saveBtn) saveBtn.disabled = false;
  }
}

/** Editor targeted by the last desktop context menu open (scene or settings doc). */
let contextMenuEditor = null;

function getContextRichEditor() {
  if (contextMenuEditor && document.body.contains(contextMenuEditor)) return contextMenuEditor;
  return getActiveRichEditor() || $("sceneContent");
}

function getSelectedManuscriptText(editorEl = null) {
  const editor = editorEl || getContextRichEditor() || $("sceneContent");
  const selection = window.getSelection();
  if (!selection || selection.rangeCount === 0 || selection.isCollapsed) {
    // Fall back to stored range text if menu stole focus.
    if (manuscriptContextRange && !manuscriptContextRange.collapsed) {
      try {
        return manuscriptContextRange.toString().trim();
      } catch (_) {
        /* ignore */
      }
    }
    return "";
  }
  if (editor && !editor.contains(selection.anchorNode) && !editor.contains(selection.focusNode)) {
    if (manuscriptContextRange && !manuscriptContextRange.collapsed) {
      try {
        return manuscriptContextRange.toString().trim();
      } catch (_) {
        /* ignore */
      }
    }
    return "";
  }
  return (selection.toString() || "").trim();
}

/** Open an online dictionary for the selected word/phrase. */
function lookupDictionaryFromSelection() {
  const raw = (pendingBaitQuote || getSelectedManuscriptText() || "").trim();
  if (!raw) {
    toast("본문에서 단어나 문장을 드래그로 선택한 뒤 다시 시도해 주세요.");
    return;
  }
  // Collapse whitespace; keep a sensible query length for dictionary URLs.
  const query = raw.replace(/\s+/g, " ").slice(0, 80);
  // Daum 사전: Korean + English (and other) in one search.
  const url = `https://dic.daum.net/search.do?q=${encodeURIComponent(query)}`;
  try {
    window.open(url, "_blank", "noopener,noreferrer");
  } catch (_) {
    toast("사전 창을 열 수 없어요. 팝업이 막혔는지 확인해 주세요.");
    return;
  }
  toast(`사전에서 「${query.length > 18 ? `${query.slice(0, 18)}…` : query}」 검색`);
}

function throwBaitFromSelection() {
  if (!state.projectId) return toast("먼저 작품을 선택해 주세요.");
  if (!state.sceneId) return toast("떡밥을 심을 회차를 먼저 열어 주세요.");
  const quote = (pendingBaitQuote || getSelectedManuscriptText() || "").trim();
  if (!quote) {
    toast("본문에서 문장을 드래그로 선택한 뒤 다시 시도해 주세요.");
    return;
  }
  // Prefill summary with a short clip of the quote.
  const summary = quote.length > 40 ? `${quote.slice(0, 40)}…` : quote;
  openBaitModal({
    kind: "plant",
    quote,
    summary,
    recoverAt: "",
    plantSceneId: state.sceneId,
    sourceSceneId: state.sceneId,
    notifyOnRecover: true,
  });
}

/* —— SuperTORY 떡밥 회수 알림 —— */
const baitNotifyShownThisSession = new Set(); // `${projectId}:${sceneId}` once per session (확인 only)

function hideBaitNotifyModal() {
  $("baitNotifyModal")?.classList.add("hidden");
  // Keep active ids until snooze handlers finish; clear when fully dismissed without snooze.
}

function showBaitRecoverNotify(sceneId, entries) {
  const modal = $("baitNotifyModal");
  const listEl = $("baitNotifyList");
  if (!modal || !listEl || !entries.length) return;
  baitNotifyActiveSceneId = Number(sceneId) || null;
  baitNotifyActiveBaitIds = entries
    .filter((e) => e.kind === "bait" && e.baitId)
    .map((e) => String(e.baitId));
  const hasBait = entries.some((e) => e.kind === "bait");
  const hasCustom = entries.some((e) => e.kind === "custom");
  if ($("baitNotifyLead")) {
    if (hasBait && hasCustom) {
      $("baitNotifyLead").textContent = "이번 회차에서 확인할 토리 알림이 있어요!";
    } else if (hasCustom && !hasBait) {
      $("baitNotifyLead").textContent = "이번 회차에 설정해 둔 알림이 있어요!";
    } else {
      $("baitNotifyLead").textContent = "이번 회차에서 떡밥 회수 예정이 있어요!";
    }
  }
  listEl.innerHTML = entries.map((b) => {
    const title = escapeHtml((b.title || "알림").replace(/\s+/g, " ").trim().slice(0, 80));
    const detail = escapeHtml((b.detail || "").replace(/\s+/g, " ").trim().slice(0, 120));
    const tag = b.kind === "bait" ? "떡밥" : "알림";
    return `<li><strong>[${tag}] ${title}</strong>${detail && detail !== title ? `<span>${detail}</span>` : ""}</li>`;
  }).join("");
  // Footer: open baits if bait present, else just dismiss
  const openVault = $("baitNotifyOpenVault");
  if (openVault) {
    openVault.textContent = hasBait ? "떡밥모음 열기" : "알림 목록 보기";
    openVault.dataset.notifyAction = hasBait ? "baits" : "notify-list";
  }
  const hasBaitIds = baitNotifyActiveBaitIds.length > 0;
  $("baitNotifySnooze1d")?.classList.toggle("hidden", !hasBaitIds);
  $("baitNotifySnoozeNextOpen")?.classList.toggle("hidden", !hasBaitIds);
  modal.classList.remove("hidden");
}

/** Clear next_open snooze on baits whose recovery scene is not the one we just opened. */
async function clearBaitNextOpenExcept(sceneId) {
  const id = Number(sceneId);
  const toClear = loadBaits().filter(
    (b) => b.snoozeUntil === "next_open" && Number(b.recoverSceneId) !== id,
  );
  if (!toClear.length) return;
  await Promise.all(
    toClear.map((b) => updateBaitOnServer(b.id, { ...b, snoozeUntil: null }).catch(() => null)),
  );
}

function maybeNotifyBaitRecovery(sceneId) {
  const id = Number(sceneId);
  if (!id || !state.projectId) return;
  const key = `${state.projectId}:${id}`;
  // Leaving a scene drops its session "already shown" flag so next_open / re-entry can work.
  for (const seen of [...baitNotifyShownThisSession]) {
    if (seen.startsWith(`${state.projectId}:`) && seen !== key) {
      baitNotifyShownThisSession.delete(seen);
    }
  }
  if (baitNotifyShownThisSession.has(key)) return;

  // Persist next_open → clear when user has left that recovery scene.
  clearBaitNextOpenExcept(id)
    .catch(() => {})
    .finally(() => {
      if (Number(state.sceneId) !== id) return;
      if (baitNotifyShownThisSession.has(key)) return;

      const entries = [];
      const nowMs = Date.now();
      for (const b of loadBaits()) {
        if (Number(b.recoverSceneId) !== id) continue;
        if (b.notifyOnRecover === false) continue;
        if (isBaitSnoozedNow(b, id, nowMs)) continue;
        entries.push({
          kind: "bait",
          baitId: b.id,
          title: (b.summary || b.quote || "떡밥").replace(/\s+/g, " ").trim(),
          detail: (b.recoverContent || b.quote || "").replace(/\s+/g, " ").trim(),
        });
      }
      for (const n of loadCustomToryNotifs()) {
        if (Number(n.sceneId) === id && n.enabled !== false) {
          entries.push({
            kind: "custom",
            title: n.title || "알림",
            detail: (n.message || n.note || "").replace(/\s+/g, " ").trim(),
          });
        }
      }
      if (!entries.length) return;
      baitNotifyShownThisSession.add(key);
      window.setTimeout(() => {
        if (Number(state.sceneId) !== id) return;
        showBaitRecoverNotify(id, entries);
      }, 280);
    });
}

async function applyBaitNotifySnooze(mode) {
  const ids = [...baitNotifyActiveBaitIds];
  if (!ids.length) {
    hideBaitNotifyModal();
    return;
  }
  let snoozeUntil = null;
  if (mode === "1d") {
    snoozeUntil = new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString();
  } else if (mode === "next_open") {
    snoozeUntil = "next_open";
  } else {
    hideBaitNotifyModal();
    return;
  }
  try {
    await Promise.all(
      ids.map((baitId) => {
        const item = loadBaits().find((b) => b.id === baitId);
        if (!item) return Promise.resolve();
        return updateBaitOnServer(baitId, { ...item, snoozeUntil });
      }),
    );
    // DB snooze owns re-show; drop session flag so leaving/returning is not blocked forever.
    if (baitNotifyActiveSceneId && state.projectId) {
      baitNotifyShownThisSession.delete(`${state.projectId}:${baitNotifyActiveSceneId}`);
    }
    hideBaitNotifyModal();
    baitNotifyActiveBaitIds = [];
    renderBaitList();
    renderToryNotifyList();
    toast(
      mode === "1d"
        ? "하루 뒤에 다시 알려 드릴게요."
        : "이 회차를 나갔다가 다시 열면 알려 드릴게요.",
    );
  } catch (error) {
    handleError(error);
  }
}

function setupBaitCollection() {
  $("newBaitButton")?.addEventListener("click", () => {
    // Settings manual entry = idea planning (not the same as body drag-plant)
    openBaitModal({ kind: "idea", quote: "", summary: "", recoverAt: "", notifyOnRecover: true });
  });
  $("baitForm")?.addEventListener("submit", (event) => {
    saveBaitFromModal(event).catch(handleError);
  });
  document.querySelectorAll("[data-close-bait]").forEach((el) => {
    el.addEventListener("click", closeBaitModal);
  });
  document.querySelectorAll("[data-close-bait-notify]").forEach((el) => {
    el.addEventListener("click", () => {
      // 확인: UI만 닫고 notifyOnRecover / snooze 유지. 세션 키는 이미 설정됨.
      hideBaitNotifyModal();
      baitNotifyActiveBaitIds = [];
    });
  });
  $("baitNotifySnooze1d")?.addEventListener("click", () => {
    applyBaitNotifySnooze("1d").catch(handleError);
  });
  $("baitNotifySnoozeNextOpen")?.addEventListener("click", () => {
    applyBaitNotifySnooze("next_open").catch(handleError);
  });
  $("baitNotifyOpenVault")?.addEventListener("click", () => {
    hideBaitNotifyModal();
    baitNotifyActiveBaitIds = [];
    const action = $("baitNotifyOpenVault")?.dataset?.notifyAction || "baits";
    if (action === "notify-list") {
      setAiPanelOpen(true);
      renderToryNotifyList();
      $("toryNotifyBox")?.scrollIntoView?.({ block: "nearest", behavior: "smooth" });
      return;
    }
    setActiveBinder("settings");
    state.openSettingsSection = "baits";
    applySettingsSectionState();
    renderBaitList();
  });
  $("baitList")?.addEventListener("click", (event) => {
    const editBtn = event.target.closest?.("[data-bait-edit]");
    if (editBtn) {
      const id = editBtn.dataset.baitEdit;
      const item = loadBaits().find((b) => b.id === id);
      if (!item) return;
      openBaitModal(item);
      return;
    }
    const delBtn = event.target.closest?.("[data-bait-delete]");
    if (delBtn) {
      const id = delBtn.dataset.baitDelete;
      const item = loadBaits().find((b) => b.id === id);
      if (!item) return;
      if (!window.confirm("이 떡밥을 삭제할까요?")) return;
      deleteBaitOnServer(id)
        .then(() => {
          renderBaitList();
          renderSettingsCodex();
          toast("떡밥을 삭제했어요.");
        })
        .catch(handleError);
    }
  });
  document.addEventListener("keydown", (event) => {
    if (event.key === "Escape" && !$("baitModal")?.classList.contains("hidden")) {
      closeBaitModal();
    }
    if (event.key === "Escape" && !$("baitNotifyModal")?.classList.contains("hidden")) {
      hideBaitNotifyModal();
      baitNotifyActiveBaitIds = [];
    }
  });
  setupSettingsSectionDrag();
  applySettingsSectionOrder();
  renderBaitList();
}

function bookmarkStorageKey(projectId = state.projectId) {
  return `${BOOKMARK_STORAGE_PREFIX}${projectId || "0"}`;
}

function loadBookmarks() {
  if (!state.projectId) return [];
  try {
    const raw = localStorage.getItem(bookmarkStorageKey());
    const arr = raw ? JSON.parse(raw) : [];
    if (!Array.isArray(arr)) return [];
    return arr
      .filter((item) => item && item.color && item.type)
      .slice(0, BOOKMARK_MAX);
  } catch (_) {
    return [];
  }
}

function saveBookmarks(list) {
  if (!state.projectId) return;
  try {
    localStorage.setItem(bookmarkStorageKey(), JSON.stringify(list.slice(0, BOOKMARK_MAX)));
  } catch (_) {
    /* ignore */
  }
}

function bookmarkColorMeta(key) {
  return BOOKMARK_COLORS.find((c) => c.key === key) || BOOKMARK_COLORS[0];
}

function nextFreeBookmarkColor(list) {
  const used = new Set(list.map((b) => b.color));
  return BOOKMARK_COLORS.find((c) => !used.has(c.key)) || null;
}

function bookmarkKey(item) {
  if (!item) return "";
  if (item.type === "scene") return `scene:${item.sceneId}`;
  if (item.type === "settings") return `settings:${item.section}`;
  return "";
}

function findBookmark(list, type, targetId) {
  if (type === "scene") {
    return list.find((b) => b.type === "scene" && Number(b.sceneId) === Number(targetId));
  }
  if (type === "settings") {
    return list.find((b) => b.type === "settings" && b.section === targetId);
  }
  return null;
}

function isOutlineReadyForBookmarks() {
  // Never treat an empty/foreign outline as "all scenes missing" — that wiped bookmarks on refresh/switch.
  return Boolean(
    state.projectId
    && state.outlineProjectId
    && Number(state.outlineProjectId) === Number(state.projectId)
  );
}

function sanitizeBookmarks(list) {
  // Settings folders can always be validated; scenes only after outline for THIS project is loaded.
  if (!isOutlineReadyForBookmarks()) {
    return (list || []).filter((item) => {
      if (!item || !item.type) return false;
      if (item.type === "settings") return Boolean(SETTINGS_BOOKMARK_META[item.section]);
      if (item.type === "scene") return Boolean(item.sceneId); // keep until we can verify
      return false;
    });
  }
  const sceneIds = new Set();
  for (const chapter of state.outline || []) {
    walkSceneTree(chapter.scenes || [], (scene) => sceneIds.add(Number(scene.id)));
  }
  return (list || []).filter((item) => {
    if (!item || !item.type) return false;
    if (item.type === "scene") return sceneIds.has(Number(item.sceneId));
    if (item.type === "settings") return Boolean(SETTINGS_BOOKMARK_META[item.section]);
    return false;
  });
}

function getSceneTitleById(sceneId) {
  for (const chapter of state.outline || []) {
    let found = "";
    walkSceneTree(chapter.scenes || [], (scene) => {
      if (Number(scene.id) === Number(sceneId)) found = scene.title || "원고";
    });
    if (found) return found;
  }
  return "원고";
}

function findSceneNodeById(sceneId) {
  const id = Number(sceneId);
  if (!id) return null;
  let found = null;
  walkBinderChapters(getBinderChaptersInOrder(), (chapter) => {
    if (found) return;
    walkSceneTree(chapter.scenes || [], (scene) => {
      if (!found && Number(scene.id) === id) found = scene;
    });
  });
  return found;
}

/** Titles treated as “no real title” → show body first sentence in the binder. */
const UNTITLED_SCENE_TITLES = new Set(["", "제목 없음", "새 씬", "새 하위 원고"]);

function isUntitledSceneTitle(title) {
  return UNTITLED_SCENE_TITLES.has(String(title || "").trim());
}

function firstSentenceFromPlain(plain) {
  const compact = String(plain || "").replace(/\s+/g, " ").trim();
  if (!compact) return "";
  const matched = compact.match(/^(.+?(?:[.。!?？…]|$))(?:\s|$)/);
  const sentence = (matched ? matched[1] : compact).trim();
  return sentence;
}

function getOutlineSceneDisplay(scene) {
  const rawTitle = String(scene?.title || "").trim();
  const preview = firstSentenceFromPlain(
    scene?.body_preview
    || scene?.content_preview
    || scene?.content_plain
    || "",
  );
  if (!isUntitledSceneTitle(rawTitle)) {
    return { label: rawTitle, tooltip: rawTitle, isPreview: false };
  }
  if (preview) {
    return {
      label: preview,
      tooltip: preview,
      isPreview: true,
    };
  }
  return {
    label: rawTitle || "제목 없음",
    tooltip: rawTitle || "제목 없음",
    isPreview: false,
  };
}

function pinnedScenesStorageKey(projectId = state.projectId) {
  return `${PINNED_SCENES_STORAGE_PREFIX}${projectId || "0"}`;
}

function loadPinnedSceneIds() {
  if (!state.projectId) return [];
  try {
    const raw = localStorage.getItem(pinnedScenesStorageKey());
    const arr = raw ? JSON.parse(raw) : [];
    if (!Array.isArray(arr)) return [];
    return arr
      .map((id) => Number(id))
      .filter((id) => Number.isFinite(id) && id > 0)
      .slice(0, PINNED_SCENES_MAX);
  } catch (_) {
    return [];
  }
}

function savePinnedSceneIds(ids) {
  if (!state.projectId) return;
  try {
    const clean = (Array.isArray(ids) ? ids : [])
      .map((id) => Number(id))
      .filter((id) => Number.isFinite(id) && id > 0)
      .slice(0, PINNED_SCENES_MAX);
    localStorage.setItem(pinnedScenesStorageKey(), JSON.stringify(clean));
  } catch (_) {
    /* ignore */
  }
}

function sanitizePinnedSceneIds(ids = loadPinnedSceneIds()) {
  const valid = new Set(
    (typeof flattenAllOutlineScenes === "function"
      ? flattenAllOutlineScenes()
      : allScenes()
    ).map((s) => Number(s.id)),
  );
  const next = (Array.isArray(ids) ? ids : [])
    .map((id) => Number(id))
    .filter((id) => valid.has(id));
  // Deduplicate while preserving pin order (first = top).
  const seen = new Set();
  const unique = [];
  for (const id of next) {
    if (seen.has(id)) continue;
    seen.add(id);
    unique.push(id);
  }
  return unique.slice(0, PINNED_SCENES_MAX);
}

function isScenePinned(sceneId) {
  return sanitizePinnedSceneIds().includes(Number(sceneId));
}

function pinSceneToTop(sceneId) {
  const id = Number(sceneId);
  if (!state.projectId) {
    toast("먼저 작품을 선택해 주세요.");
    return;
  }
  if (!Number.isFinite(id) || id <= 0) return;
  // Newest pin goes first; previously pinned scenes shift down and stay until unpinned.
  let list = sanitizePinnedSceneIds().filter((x) => x !== id);
  list.unshift(id);
  savePinnedSceneIds(list);
  if (typeof renderOutline === "function" && Array.isArray(state.outline)) {
    renderOutline(state.outline);
  }
  toast("상단에 고정했어요.");
}

function unpinSceneFromTop(sceneId) {
  const id = Number(sceneId);
  if (!Number.isFinite(id) || id <= 0) return;
  const before = sanitizePinnedSceneIds();
  const list = before.filter((x) => x !== id);
  if (list.length === before.length) return;
  savePinnedSceneIds(list);
  if (typeof renderOutline === "function" && Array.isArray(state.outline)) {
    renderOutline(state.outline);
  }
  toast("상단 고정을 해제했어요.");
}

function toggleScenePin(sceneId) {
  if (isScenePinned(sceneId)) unpinSceneFromTop(sceneId);
  else pinSceneToTop(sceneId);
}

function renderPinnedOutlineSectionHtml() {
  const pinnedIds = sanitizePinnedSceneIds();
  if (pinnedIds.length !== loadPinnedSceneIds().length) {
    savePinnedSceneIds(pinnedIds);
  }
  if (!pinnedIds.length) return "";
  const rows = pinnedIds.map((sid) => {
    const scene = findSceneNodeById(sid);
    const display = getOutlineSceneDisplay(scene || { id: sid, title: getSceneTitleById(sid) });
    const titleAttr = escapeHtml(display.tooltip);
    const chapterId = findChapterIdForScene(sid) || "";
    const active = Number(state.sceneId) === Number(sid) ? "active" : "";
    const previewClass = display.isPreview ? " is-body-preview" : "";
    return `
      <div class="outline-pin-item" data-pinned-scene="${sid}">
        <button
          type="button"
          class="scene-link outline-pin-link ${active}"
          data-scene="${sid}"
          data-chapter-id="${chapterId}"
          data-pinned="1"
          title="${titleAttr} · 상단 고정 · 우클릭: 고정 해제"
        >
          <span class="outline-pin-badge" aria-hidden="true">고</span>
          <span class="scene-title${previewClass}">${escapeHtml(display.label)}</span>
        </button>
      </div>`;
  }).join("");
  return `
    <section class="outline-pin-section" aria-label="상단 고정">
      <div class="outline-pin-label">상단 고정</div>
      <div class="outline-pin-list" role="list">${rows}</div>
    </section>`;
}

function addOrToggleBookmark(entry) {
  if (!state.projectId) {
    toast("먼저 작품을 선택해 주세요.");
    return null;
  }
  let list = loadBookmarks();
  const existing = findBookmark(
    list,
    entry.type,
    entry.type === "scene" ? entry.sceneId : entry.section,
  );
  if (existing) {
    list = list.filter((b) => bookmarkKey(b) !== bookmarkKey(existing));
    saveBookmarks(list);
    renderBookmarkBar();
    markBookmarkedTargets();
    toast("북마크를 해제했어요.");
    return null;
  }
  if (list.length >= BOOKMARK_MAX) {
    toast(`북마크는 최대 ${BOOKMARK_MAX}개까지, 색마다 하나씩 쓸 수 있어요.`);
    return null;
  }
  const color = nextFreeBookmarkColor(list);
  if (!color) {
    toast("남은 북마크 색이 없어요.");
    return null;
  }
  const item = {
    id: `bm-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 6)}`,
    type: entry.type,
    color: color.key,
    title: entry.title || "",
    note: "",
    sceneId: entry.type === "scene" ? Number(entry.sceneId) : undefined,
    section: entry.type === "settings" ? entry.section : undefined,
  };
  list.push(item);
  saveBookmarks(list);
  // 아이콘 행 패널을 열어 이유를 바로 적을 수 있게
  openBookmarkListPanel({ focusNote: true });
  renderBookmarkBar();
  markBookmarkedTargets();
  toast(`${color.label} 북마크로 고정했어요.`);
  return item;
}

const BOOKMARK_NOTE_MAX = 200;

function updateBookmarkNote(bookmarkId, note) {
  if (!bookmarkId) return;
  const list = loadBookmarks();
  const item = list.find((b) => b.id === bookmarkId);
  if (!item) return;
  const next = String(note || "").slice(0, BOOKMARK_NOTE_MAX);
  if ((item.note || "") === next) return;
  item.note = next;
  saveBookmarks(list);
}

function isBookmarkListPanelOpen() {
  const panel = $("bookmarkListPanel");
  return Boolean(panel && !panel.classList.contains("hidden"));
}

function syncBookmarkListButton(list) {
  const btn = $("bookmarkListButton");
  const badge = $("bookmarkListCount");
  const count = Array.isArray(list) ? list.length : (state.projectId ? loadBookmarks().length : 0);
  const open = isBookmarkListPanelOpen();
  if (btn) {
    btn.setAttribute("aria-pressed", open ? "true" : "false");
    btn.setAttribute("aria-expanded", open ? "true" : "false");
    btn.classList.toggle("is-list-open", open);
    btn.title = count
      ? `북마크 ${count}개 · 클릭: 목록 열기/닫기 · 각 항목에 이유 적기`
      : "북마크 목록 · 회차·설정집에서 우클릭으로 추가";
  }
  if (badge) {
    const show = count > 0;
    badge.textContent = String(count);
    badge.classList.toggle("hidden", !show);
    badge.setAttribute("aria-hidden", show ? "false" : "true");
  }
}

function positionBookmarkListPanel() {
  const panel = $("bookmarkListPanel");
  const btn = $("bookmarkListButton");
  if (!panel || !btn || panel.classList.contains("hidden")) return;
  const rect = btn.getBoundingClientRect();
  const pad = 8;
  const pw = panel.offsetWidth || 280;
  const ph = panel.offsetHeight || 240;
  let left = rect.left + (rect.width / 2) - (pw / 2);
  let top = rect.bottom + 6;
  if (left < pad) left = pad;
  if (left + pw > window.innerWidth - pad) left = Math.max(pad, window.innerWidth - pw - pad);
  if (top + ph > window.innerHeight - pad) top = Math.max(pad, rect.top - ph - 6);
  panel.style.left = `${left}px`;
  panel.style.top = `${top}px`;
}

function closeBookmarkListPanel() {
  const panel = $("bookmarkListPanel");
  panel?.classList.add("hidden");
  syncBookmarkListButton(state.projectId ? sanitizeBookmarks(loadBookmarks()) : []);
}

function openBookmarkListPanel(options = {}) {
  const panel = $("bookmarkListPanel");
  if (!panel) return;
  if (!state.projectId) {
    toast("먼저 작품을 선택해 주세요.");
    return;
  }
  if ($("formatToolbarShell")?.classList.contains("is-collapsed")
    || document.querySelector('[data-toolbar-row="format-icons"]')?.classList.contains("is-collapsed")) {
    applyMsToolbarCollapsed?.("format-icons", false, { toastMsg: false });
  }
  panel.classList.remove("hidden");
  renderBookmarkBar({ persistSanitize: false });
  syncBookmarkListButton(sanitizeBookmarks(loadBookmarks()));
  requestAnimationFrame(() => {
    positionBookmarkListPanel();
    if (options.focusNote) {
      $("bookmarkBar")?.querySelector(".bookmark-item-note")?.focus();
    }
  });
}

function toggleBookmarkListPanel() {
  if (!state.projectId) {
    toast("먼저 작품을 선택해 주세요.");
    return;
  }
  if (isBookmarkListPanelOpen()) {
    closeBookmarkListPanel();
    return;
  }
  const list = sanitizeBookmarks(loadBookmarks());
  openBookmarkListPanel({ focusNote: list.length > 0 });
  if (!list.length) {
    toast("북마크한 항목이 없어요. 회차·설정집에서 우클릭으로 추가해 보세요.");
  }
}

function removeBookmarkById(bookmarkId) {
  let list = loadBookmarks().filter((b) => b.id !== bookmarkId);
  saveBookmarks(list);
  renderBookmarkBar();
  markBookmarkedTargets();
  toast("북마크를 해제했어요.");
}

function setHeaderNoticeFillState(sectionId, hasItems) {
  const section = $(sectionId);
  if (!section) return;
  section.classList.toggle("has-items", Boolean(hasItems));
  section.classList.toggle("is-empty", !hasItems);
}

/** 아이콘 행 북마크 패널 목록 · 목차 하단에는 그리지 않음. */
function renderBookmarkBar(options = {}) {
  const bar = $("bookmarkBar");
  const raw = state.projectId ? loadBookmarks() : [];
  const list = state.projectId ? sanitizeBookmarks(raw) : [];
  // Only persist cleanup when outline for this project is loaded.
  const canPersistCleanup = options.persistSanitize !== false && isOutlineReadyForBookmarks();
  if (state.projectId && canPersistCleanup && list.length !== raw.length) {
    saveBookmarks(list);
  }
  syncBookmarkListButton(list);
  if (!bar) return;

  if (!state.projectId || !list.length) {
    bar.innerHTML = `<p class="bookmark-list-empty">북마크한 항목이 없어요.</p>`;
    if (isBookmarkListPanelOpen()) positionBookmarkListPanel();
    return;
  }

  const activeEl = document.activeElement;
  const keepFocusId = activeEl?.classList?.contains("bookmark-item-note")
    ? activeEl.dataset.bookmarkId
    : null;
  const keepSelStart = keepFocusId != null ? activeEl.selectionStart : null;
  const keepSelEnd = keepFocusId != null ? activeEl.selectionEnd : null;

  bar.innerHTML = list.map((item) => {
    const color = bookmarkColorMeta(item.color);
    const title = escapeHtml(item.title || (item.type === "scene" ? "원고" : "설정"));
    const kind = item.type === "scene" ? "원고" : "설정집";
    const note = escapeHtml(item.note || "");
    const active = item.type === "scene" && Number(item.sceneId) === Number(state.sceneId)
      ? "is-active"
      : "";
    const idAttr = escapeHtml(item.id);
    return `
      <div
        class="bookmark-item ${active}"
        data-bookmark-id="${idAttr}"
        style="--bm-color:${color.hex}"
        role="listitem"
      >
        <div class="bookmark-item-row">
          <button
            type="button"
            class="bookmark-chip"
            data-bookmark-open="${idAttr}"
            title="${title} (${kind} · ${color.label}) — 클릭: 열기 · 우클릭: 메뉴"
            aria-label="${title} 북마크 열기"
          ></button>
          <button
            type="button"
            class="bookmark-item-title"
            data-bookmark-open="${idAttr}"
            title="${title} (${kind}) — 클릭: 열기 · 우클릭: 메뉴"
          >${title}</button>
          <button
            type="button"
            class="bookmark-item-remove"
            data-bookmark-remove="${idAttr}"
            title="북마크 해제"
            aria-label="${title} 북마크 해제"
          >×</button>
        </div>
        <input
          type="text"
          class="bookmark-item-note"
          data-bookmark-id="${idAttr}"
          value="${note}"
          maxlength="${BOOKMARK_NOTE_MAX}"
          placeholder="북마크 이유 (예: 복선 확인, 수정 필요)"
          title="이 북마크를 단 이유"
          autocomplete="off"
          spellcheck="true"
        />
      </div>`;
  }).join("");

  bar.querySelectorAll("[data-bookmark-open]").forEach((btn) => {
    btn.addEventListener("click", (event) => {
      event.preventDefault();
      openBookmark(btn.dataset.bookmarkOpen).catch(handleError);
    });
    btn.addEventListener("contextmenu", (event) => {
      event.preventDefault();
      event.stopPropagation();
      showBookmarkContextMenu(event.clientX, event.clientY, btn.dataset.bookmarkOpen);
    });
  });
  bar.querySelectorAll("[data-bookmark-remove]").forEach((btn) => {
    btn.addEventListener("click", (event) => {
      event.preventDefault();
      event.stopPropagation();
      removeBookmarkById(btn.dataset.bookmarkRemove);
    });
  });
  bar.querySelectorAll(".bookmark-item-note").forEach((input) => {
    input.addEventListener("input", () => {
      updateBookmarkNote(input.dataset.bookmarkId, input.value);
    });
    input.addEventListener("keydown", (event) => {
      if (event.key === "Enter") {
        event.preventDefault();
        input.blur();
      }
      event.stopPropagation();
    });
    input.addEventListener("click", (event) => event.stopPropagation());
    input.addEventListener("contextmenu", (event) => event.stopPropagation());
  });

  if (keepFocusId) {
    const restore = bar.querySelector(`.bookmark-item-note[data-bookmark-id="${CSS.escape(keepFocusId)}"]`);
    if (restore) {
      restore.focus();
      try {
        if (keepSelStart != null && keepSelEnd != null) {
          restore.setSelectionRange(keepSelStart, keepSelEnd);
        }
      } catch (_) {
        /* ignore */
      }
    }
  }
  if (isBookmarkListPanelOpen()) {
    requestAnimationFrame(() => positionBookmarkListPanel());
  }
}

function renderHeaderIdeaBar() {
  const bar = $("headerIdeaBar");
  if (!bar) return;
  const ideas = (state.projectId ? state.ideas : []).filter(ideaIsPinned);
  setHeaderNoticeFillState("headerIdeaNotice", ideas.length > 0);
  if (!ideas.length) {
    bar.innerHTML = "";
    return;
  }
  bar.innerHTML = ideas.slice(0, 8).map((idea) => {
    const label = escapeHtml(idea.title || ideaPreview(idea.body_md, 28) || "메모");
    return (
      `<button type="button" class="header-idea-chip is-pinned color-${escapeHtml(idea.color || "yellow")}" `
      + `data-header-idea="${idea.id}" title="${label} · 목차 하단 고정" role="listitem">`
      + `<span class="header-idea-chip-pin" aria-hidden="true">${ideaPinGlyphHtml(14)}</span>`
      + `<span class="header-idea-chip-label">${label}</span>`
      + `</button>`
    );
  }).join("");
  bar.querySelectorAll("[data-header-idea]").forEach((btn) => {
    btn.addEventListener("click", () => openIdeaBoard(Number(btn.dataset.headerIdea)));
  });
}

function setupHeaderNotices() {
  renderHeaderIdeaBar();
}

function setupBookmarkListPanel() {
  if (setupBookmarkListPanel._bound) return;
  setupBookmarkListPanel._bound = true;
  $("bookmarkListClose")?.addEventListener("click", (event) => {
    event.preventDefault();
    closeBookmarkListPanel();
  });
  document.addEventListener("click", (event) => {
    if (!isBookmarkListPanelOpen()) return;
    if (event.target.closest?.("#bookmarkListPanel, #bookmarkListButton, #bookmarkContextMenu")) return;
    closeBookmarkListPanel();
  });
  document.addEventListener("keydown", (event) => {
    if (event.key === "Escape" && isBookmarkListPanelOpen()) {
      closeBookmarkListPanel();
    }
  });
  window.addEventListener("resize", () => {
    if (isBookmarkListPanelOpen()) positionBookmarkListPanel();
  });
}

function ensureSceneBookmarkMark(el, colorKey) {
  if (!el) return;
  // 작성 상태 열 정렬을 위해 북마크는 항상 고정 폭 슬롯 안에만 둔다.
  let slot = null;
  for (const child of el.children) {
    if (child.classList?.contains("scene-bookmark-slot")) {
      slot = child;
      break;
    }
  }
  if (!slot) {
    slot = document.createElement("span");
    slot.className = "scene-bookmark-slot";
    slot.setAttribute("aria-hidden", "true");
    let statusEl = null;
    for (const child of el.children) {
      if (
        child.classList?.contains("scene-status")
        || child.classList?.contains("scene-complete-badge")
        || child.classList?.contains("scene-status-slot")
      ) {
        statusEl = child;
        break;
      }
    }
    if (statusEl) el.insertBefore(slot, statusEl);
    else el.insertBefore(slot, el.firstChild);
  }
  let mark = slot.querySelector(".scene-bookmark-mark");
  if (!colorKey) {
    if (mark) mark.remove();
    slot.removeAttribute("title");
    return;
  }
  const meta = bookmarkColorMeta(colorKey);
  if (!mark) {
    mark = document.createElement("span");
    mark.className = "scene-bookmark-mark";
    mark.setAttribute("aria-label", "북마크");
    slot.appendChild(mark);
  }
  mark.style.setProperty("--bm-color", meta.hex);
  mark.title = `북마크 · ${meta.label || ""}`;
  slot.title = mark.title;
}

function markBookmarkedTargets() {
  const list = loadBookmarks();
  const sceneMap = new Map(
    list.filter((b) => b.type === "scene").map((b) => [Number(b.sceneId), b.color]),
  );
  const settingsMap = new Map(
    list.filter((b) => b.type === "settings").map((b) => [b.section, b.color]),
  );

  document.querySelectorAll(".scene-link[data-scene]").forEach((el) => {
    const colorKey = sceneMap.get(Number(el.dataset.scene));
    el.classList.toggle("is-bookmarked", Boolean(colorKey));
    if (colorKey) el.style.setProperty("--bm-color", bookmarkColorMeta(colorKey).hex);
    else el.style.removeProperty("--bm-color");
    // 목록 재렌더 없이 토글해도 북마크 마크가 작성 상태 왼쪽에 생기도록
    ensureSceneBookmarkMark(el, colorKey || null);
  });

  document.querySelectorAll(".settings-box[data-settings-section]").forEach((box) => {
    const section = box.dataset.settingsSection;
    const colorKey = settingsMap.get(section);
    box.classList.toggle("is-bookmarked", Boolean(colorKey));
    if (colorKey) box.style.setProperty("--bm-color", bookmarkColorMeta(colorKey).hex);
    else box.style.removeProperty("--bm-color");
  });
}

async function openBookmark(bookmarkId) {
  const item = loadBookmarks().find((b) => b.id === bookmarkId);
  if (!item) {
    renderBookmarkBar();
    return toast("북마크를 찾을 수 없어요.");
  }
  if (item.type === "scene") {
    await openScene(item.sceneId);
    return;
  }
  if (item.type === "settings") {
    const meta = SETTINGS_BOOKMARK_META[item.section];
    if (!meta) return toast("설정 항목을 열 수 없어요.");
    setActiveBinder("settings");
    state.openSettingsSection = item.section;
    applySettingsSectionState();
    await meta.open();
  }
}

