  const projects = Array.isArray(state.projects) ? state.projects : [];
  if (hint) {
    hint.textContent = projects.length
      ? `작품 ${projects.length}개`
      : "아직 작품이 없어요.";
  }
  if (!projects.length) {
    list.innerHTML = `<p class="hint trash-empty">삭제할 작품이 없어요. 먼저 작품을 만들어 주세요.</p>`;
    return;
  }
