function getAppVersionSync() {
  try {
    if (typeof window !== "undefined" && window.__SUPERTORY_VERSION) {
      return String(window.__SUPERTORY_VERSION);
    }
  } catch (_) { /* ignore */ }
  return APP_VERSION_FALLBACK;
}

async function resolveAppVersion() {
  try {
    if (window.electronAPI?.getVersion) {
      const v = await window.electronAPI.getVersion();
      if (v) {
        window.__SUPERTORY_VERSION = String(v);
        return String(v);
      }
    }
  } catch (_) { /* ignore */ }
  return getAppVersionSync();
}

function refreshAdminInfoPanel() {
  resolveAppVersion().then((v) => {
    if ($("adminAppVersion")) $("adminAppVersion").textContent = v;
  });
  const runtime = $("adminAppRuntime");
  if (runtime) {
    const isEl = Boolean(window.electronAPI);
    runtime.textContent = isEl ? "데스크톱 앱 (Electron)" : "브라우저 · 로컬 서버";
  }
  refreshAiStatus().catch(handleError);
}

function refreshAdminAccountPanel() {
  if ($("adminUserStatus")) $("adminUserStatus").textContent = "로컬 사용자";
  if ($("adminUserDisplayName")) $("adminUserDisplayName").textContent = "이 기기";
  if ($("adminUserAccount")) $("adminUserAccount").textContent = "로그인 없음 (로컬)";
  if ($("adminUserPlan")) $("adminUserPlan").textContent = "로컬 무료 (전체 기능)";
  if ($("adminUserPlanPeriod")) $("adminUserPlanPeriod").textContent = "제한 없음";
  if ($("adminUserPlanPerks")) {
    $("adminUserPlanPerks").textContent = "로컬 저장 · AI(구성 시) · 가져오기/내보내기";
  }
  if ($("adminUserPaymentMethod")) $("adminUserPaymentMethod").textContent = "해당 없음";
  if ($("adminUserPaymentLast")) $("adminUserPaymentLast").textContent = "—";
  if ($("adminUserPaymentReceipt")) $("adminUserPaymentReceipt").textContent = "—";
}

function renderAdminHelpManual(filterText = "") {
  const host = $("adminHelpManual");
  if (!host) return;
  const q = String(filterText || "").trim().toLowerCase();
  const tokens = q ? q.split(/\s+/).filter(Boolean) : [];
  const matched = HELP_MANUAL_SECTIONS.filter((sec) => {
    if (!tokens.length) return true;
    const hay = `${sec.title} ${sec.keywords} ${sec.body.join(" ")}`.toLowerCase();
    return tokens.every((t) => hay.includes(t));
  });
  const hint = $("adminHelpSearchHint");
  if (hint) {
    hint.textContent = tokens.length
      ? (matched.length ? `검색 결과 ${matched.length}개` : "검색 결과가 없습니다. 다른 단어를 시도해 보세요.")
      : `설명서 ${HELP_MANUAL_SECTIONS.length}개 항목`;
  }
  if (!matched.length) {
    host.innerHTML = `<p class="hint trash-empty">일치하는 도움말이 없습니다.</p>`;
    return;
  }
  host.innerHTML = matched.map((sec) => `
    <article class="admin-help-article" data-help-id="${escapeHtml(sec.id)}" id="help-sec-${escapeHtml(sec.id)}">
      <h5 class="admin-help-article-title">${escapeHtml(sec.title)}</h5>
      ${sec.body.map((p) => `<p>${escapeHtml(p)}</p>`).join("")}
    </article>
  `).join("");
}

function renderAdminHelpQa() {
  const host = $("adminHelpQa");
  if (!host) return;
  if (!HELP_QA_ITEMS.length) {
    host.innerHTML = `
      <div class="admin-qa-empty">
        <p class="hint">아직 등록된 Q&amp;A가 없습니다.</p>
        <p class="hint">업데이트로 질문·답변이 추가되면 이 목록에 표시됩니다.</p>
      </div>`;
    return;
  }
  host.innerHTML = HELP_QA_ITEMS.map((item, index) => `
    <details class="admin-qa-item" data-qa-id="${escapeHtml(item.id || String(index))}">
      <summary>${escapeHtml(item.q)}</summary>
      <div class="admin-qa-a">${escapeHtml(item.a)}</div>
    </details>
  `).join("");
}

/** Open mail client without showing the address in the UI. */
function openDeveloperContact() {
  const local = ["cult", "noni"].join("");
  const host = ["gmail", "com"].join(".");
  const to = `${local}\u0040${host}`;
  const ver = getAppVersionSync();
  const subject = encodeURIComponent(`[SuperTory] 문의 (v${ver})`);
  const body = encodeURIComponent(
    `앱 버전: ${ver}\n실행: ${window.electronAPI ? "Electron" : "브라우저"}\n\n문의 내용:\n`,
  );
  const href = `mailto:${to}?subject=${subject}&body=${body}`;
  try {
    const a = document.createElement("a");
    a.href = href;
    a.rel = "noopener";
    a.style.display = "none";
    document.body.appendChild(a);
    a.click();
    a.remove();
    toast("메일 작성 창을 열었습니다.");
  } catch (_) {
    toast("메일 앱을 열 수 없습니다. 시스템 기본 메일 설정을 확인해 주세요.");
  }
}

/* —— First-run onboarding tutorial (driver.js) —— */
const TUTORIAL_COMPLETED_KEY = "tutorial_completed";
let onboardingDriver = null;
let tutorialUiSnapshot = null;

function isTutorialCompleted() {
  try {
    return localStorage.getItem(TUTORIAL_COMPLETED_KEY) === "1";
  } catch (_) {
    return false;
  }
}

function markTutorialCompleted() {
  try {
    localStorage.setItem(TUTORIAL_COMPLETED_KEY, "1");
  } catch (_) {
    /* private mode */
  }
}

function getDriverFactory() {
  return window.driver?.js?.driver || window.driver?.driver || null;
}

function prepareTutorialUi() {
  if (tutorialUiSnapshot) return;
  tutorialUiSnapshot = {
    welcomeHidden: $("welcome")?.classList.contains("hidden"),
    workspaceHidden: $("sceneWorkspace")?.classList.contains("hidden"),
    aiCollapsed: document.body.classList.contains("ai-panel-collapsed"),
  };
  closeAdminModal?.();
  hideGenreContextMenu?.();
  hidePurposeContextMenu?.();
  hideUiFeatureContextMenu?.();
  $("welcome")?.classList.add("hidden");
  $("sceneWorkspace")?.classList.remove("hidden");
  $("sceneWorkspace")?.classList.add("tutorial-force-visible");
  if (typeof setAiPanelOpen === "function") setAiPanelOpen(true);
  else document.body.classList.remove("ai-panel-collapsed");
  // Feature bar may be collapsed — reopen shell if present
  $("sceneFeatureBarShell")?.classList.remove("is-collapsed");
  $("sceneFeatureBarReopenButton")?.classList.add("hidden");
  if ($("sceneFeatureBarReopenButton")) $("sceneFeatureBarReopenButton").hidden = true;
  syncMsChromeReopenStrip?.();
}

function restoreTutorialUi() {
  const snap = tutorialUiSnapshot;
  tutorialUiSnapshot = null;
  $("sceneWorkspace")?.classList.remove("tutorial-force-visible");
  if (!snap) return;
  if (!snap.welcomeHidden) $("welcome")?.classList.remove("hidden");
  if (snap.workspaceHidden) $("sceneWorkspace")?.classList.add("hidden");
  if (snap.aiCollapsed) {
    if (typeof setAiPanelOpen === "function") setAiPanelOpen(false);
    else document.body.classList.add("ai-panel-collapsed");
  }
}

function destroyOnboardingDriver() {
  try {
    onboardingDriver?.destroy?.();
  } catch (_) {
    /* ignore */
  }
  onboardingDriver = null;
  restoreTutorialUi();
}

function buildOnboardingSteps() {
  // Exact copy — do not polish.
  return [
    {
      element: "#writingLogButton",
      popover: {
        title: "기록",
        description: "지난 일주일 글자 수를 확인해요. 우클릭하면 더 많은 설정이 있어요.",
        side: "bottom",
        align: "start",
      },
    },
    {
      element: "#outlineTocHeading",
      popover: {
        title: "목차",
        description: "클릭하면 목차를 한눈에 볼 수 있어요. 우클릭으로 바인더 글자 크기도 조절할 수 있어요.",
        side: "right",
        align: "start",
      },
    },
    {
      element: "#aiTabTools",
      popover: {
        title: "도우미",
        description: "토리 모드를 설정할 수 있어요. 팩폭 잘하는 투덜이는 어때요?",
        side: "left",
        align: "start",
      },
    },
    {
      element: "#sceneContent",
      popover: {
        title: "떡밥",
        description: "떡밥을 던져 놓으면 회수 시기를 놓치지 않아요. 사용해보실래요?",
        side: "left",
        align: "start",
      },
    },
    {
      element: "#outline",
      popover: {
        title: "바인더",
        description: "폴더와 원고를 자유자재로 배치해요. 끌어다 놓기만 하세요.",
        side: "right",
        align: "center",
      },
    },
    {
      element: "#adminModeButton",
      popover: {
        title: "숨긴 기능",
        description: "안 쓰는 기능은 숨길 수 있어요. 미니멀리스트를 위한 팁입니당~",
        side: "bottom",
        align: "end",
      },
    },
  ];
}

/**
 * @param {{ force?: boolean }} [options]
 */
function startOnboardingTutorial(options = {}) {
  const force = Boolean(options.force);
  if (!force && isTutorialCompleted()) return false;
  const createDriver = getDriverFactory();
  if (typeof createDriver !== "function") {
    console.warn("[SuperTory] driver.js not loaded");
    return false;
  }
  destroyOnboardingDriver();
  prepareTutorialUi();

  onboardingDriver = createDriver({
    animate: true,
    allowClose: true,
    overlayOpacity: 0.55,
    stagePadding: 8,
    stageRadius: 8,
    smoothScroll: true,
    showProgress: true,
    progressText: "{{current}} / {{total}}",
    nextBtnText: "다음",
    prevBtnText: "이전",
    doneBtnText: "완료",
    showButtons: ["next", "previous", "close"],
    popoverClass: "supertory-tutorial-popover",
    steps: buildOnboardingSteps(),
    onPopoverRender: (popover) => {
      if (popover?.closeButton) {
        popover.closeButton.textContent = "건너뛰기";
        popover.closeButton.setAttribute("aria-label", "건너뛰기");
        popover.closeButton.title = "건너뛰기";
        popover.closeButton.classList.add("driver-popover-skip-btn");
      }
    },
    onDestroyed: () => {
      markTutorialCompleted();
      onboardingDriver = null;
      restoreTutorialUi();
    },
  });
  onboardingDriver.drive(0);
  return true;
}

function maybeStartOnboardingTutorial() {
  if (isTutorialCompleted()) return;
  window.setTimeout(() => {
    startOnboardingTutorial({ force: false });
  }, 700);
}

function setupAdminMode() {
  $("adminModeButton")?.addEventListener("click", () => openAdminModal("info"));
  document.querySelectorAll("[data-close-admin]").forEach((el) => {
    el.addEventListener("click", closeAdminModal);
  });
  document.querySelectorAll("#adminModal .admin-tab").forEach((btn) => {
    btn.addEventListener("click", () => setAdminTab(btn.dataset.adminTab));
  });
  $("adminHelpSearch")?.addEventListener("input", (event) => {
    renderAdminHelpManual(event.target.value);
  });
  $("adminContactDevButton")?.addEventListener("click", (event) => {
    event.preventDefault();
    openDeveloperContact();
  });
  $("adminReplayTutorialButton")?.addEventListener("click", (event) => {
    event.preventDefault();
    closeAdminModal();
    window.setTimeout(() => startOnboardingTutorial({ force: true }), 120);
  });
  $("refreshTrashButton")?.addEventListener("click", () => {
    loadTrashList().catch(handleError);
  });
  $("emptyTrashButton")?.addEventListener("click", () => {
    emptyProjectTrash().catch(handleError);
  });
  $("trashList")?.addEventListener("click", (event) => {
    const restoreBtn = event.target.closest?.("[data-trash-restore]");
    if (restoreBtn) {
      event.preventDefault();
      restoreTrashedScene(restoreBtn.dataset.trashRestore).catch(handleError);
      return;
    }
    const purgeBtn = event.target.closest?.("[data-trash-purge]");
    if (purgeBtn) {
      event.preventDefault();
      const row = purgeBtn.closest(".trash-item");
      const title = row?.querySelector(".trash-item-title")?.textContent || "";
      purgeTrashedScene(purgeBtn.dataset.trashPurge, title).catch(handleError);
    }
  });
  $("refreshAdminProjectsButton")?.addEventListener("click", () => {
    loadProjects(state.projectId).then(() => renderAdminProjectList()).catch(handleError);
  });
  $("refreshIndexRebuildButton")?.addEventListener("click", () => {
    loadIndexRebuildOverview({ keepSelection: true }).catch(handleError);
  });
  $("indexRebuildList")?.addEventListener("change", (event) => {
    const input = event.target.closest?.("[data-index-rebuild-check]");
    if (!input) return;
    const id = Number(input.dataset.indexRebuildCheck);
    if (!id) return;
    if (input.checked) indexRebuildSelected.add(id);
    else indexRebuildSelected.delete(id);
    syncIndexRebuildStartButton();
  });
  $("indexRebuildStartButton")?.addEventListener("click", () => {
    openIndexRebuildConfirm();
  });
  document.querySelectorAll("[data-close-index-rebuild-confirm]").forEach((el) => {
    el.addEventListener("click", closeIndexRebuildConfirm);
  });
  $("indexRebuildConfirmStart")?.addEventListener("click", () => {
    startIndexRebuildFromAdmin().catch(handleError);
  });
  $("adminProjectList")?.addEventListener("click", (event) => {
    const renameBtn = event.target.closest?.("[data-admin-rename-project]");
    if (renameBtn) {
      event.preventDefault();
      renameProjectFromAdmin(renameBtn.dataset.adminRenameProject).catch(handleError);
      return;
    }
    const delBtn = event.target.closest?.("[data-admin-delete-project]");
    if (!delBtn) return;
    event.preventDefault();
    deleteProjectFromAdmin(delBtn.dataset.adminDeleteProject).catch(handleError);
  });
  setupUiFeatureHideSystem();
  renderAdminHelpManual();
  renderAdminHelpQa();
  refreshAdminInfoPanel();
  refreshAdminAccountPanel();
  setupAutoUpdateUi();
}

