/** Keep / remove the runtime pure B/W sheet (beats stale styles.css + hardcoded tints). */
function syncEinkBwForceStyle(theme) {
  const id = normalizeUiThemeId(theme);
  let el = document.getElementById(EINK_BW_STYLE_ID);
  if (id !== "eink") {
    el?.remove();
    return;
  }
  const css = EINK_BW_FORCE_CSS;
  window.__supertoryEinkBwCss = css;
  if (!el) {
    el = document.createElement("style");
    el.id = EINK_BW_STYLE_ID;
  }
  el.textContent = css;
  document.head.appendChild(el);
}

/** Apply a named theme (`light` | `sand` | `dark` | `cabin` | `study` | `library` | `classroom` | `attic` | `eink` | `cloud-walk` | `spring-garden` | `sunset-window` | `silver-fog`). */
function applyUiTheme(themeName, { announce = false } = {}) {
  const prev = normalizeUiThemeId(getUiTheme());
  const next = normalizeUiThemeId(themeName || "light");
  const scheme = uiThemeScheme(next);
  document.documentElement.setAttribute("data-theme", next);
  document.documentElement.setAttribute("data-ui-theme", next);
  document.documentElement.setAttribute("data-ui-scheme", scheme);
  if (document.body) {
    document.body.setAttribute("data-theme", next);
    document.body.setAttribute("data-ui-theme", next);
    document.body.setAttribute("data-ui-scheme", scheme);
  }
  try {
    localStorage.setItem(UI_THEME_STORAGE_KEY, next);
    localStorage.setItem(UI_THEME_STORAGE_KEY_LEGACY, next);
  } catch (_) {
    /* private mode */
  }
  rememberLightUiTheme(next);
  updateUiThemeToggleButton(next);
  syncEinkBwForceStyle(next);
  syncEinkEditorPaperLock(next);
  try {
    syncUiThemeWritingPageTheme(prev, next);
  } catch (err) {
    console.warn("[supertory] ui theme writing page sync failed", err);
  }
  try { syncUiThemePageColorSwatch(); } catch (_) { /* ignore */ }
  try { refreshGoalBarColorsFromThemeAndOverrides?.(); } catch (_) { /* ignore */ }
  // After CSS vars apply, sync Windows caption strip to --chrome-bg / --ink.
  requestAnimationFrame(() => {
    syncElectronTitleBarTheme(next);
  });
  renderAdminThemeList();
  if (announce) {
    toast(`「${uiThemeToastLabel(next)}」로 바꿨어요.`);
  }
  return next;
}

function setTheme(themeName, options = {}) {
  return applyUiTheme(themeName, options);
}

function setUiTheme(theme, options = {}) {
  return applyUiTheme(theme, options);
}

function toggleUiTheme() {
  const current = getUiTheme();
  const idx = UI_THEME_CYCLE.indexOf(current);
  const next = UI_THEME_CYCLE[(idx < 0 ? 0 : idx + 1) % UI_THEME_CYCLE.length];
  applyUiTheme(next, { announce: true });
}

function renderAdminThemeList() {
  const host = $("adminThemeList");
  if (!host) return;
  if (host.dataset.filled !== "1") {
    host.innerHTML = UI_THEME_GROUPS.map((group) => {
      const sub = group.subtitle ? ` [${escapeHtml(group.subtitle)}]` : "";
      const heading = `${group.emoji} ${escapeHtml(group.number)}. ${escapeHtml(group.title)}${sub}`;
      const buttons = group.themes.map((item) => {
        const preset = UI_THEME_PRESETS.find((t) => t.id === item.id) || { id: item.id, emoji: "", short: item.id };
        const name = `${preset.emoji || ""} ${preset.short || item.id}`.trim();
        const caption = item.caption ? `<span class="theme-option-caption">${escapeHtml(item.caption)}</span>` : "";
        return `<button type="button" role="option" data-ui-theme-pick="${escapeHtml(item.id)}">
          <span class="theme-option-name">${escapeHtml(name)}</span>${caption}
        </button>`;
      }).join("");
      return `<section class="theme-option-group" data-theme-group="${escapeHtml(group.id)}">
        <h4 class="theme-option-group-title">${heading}</h4>
        <p class="theme-option-group-blurb">${escapeHtml(group.blurb)}</p>
        <div class="theme-option-group-grid">${buttons}</div>
      </section>`;
    }).join("");
    host.dataset.filled = "1";
  }
  const current = getUiTheme();
  host.querySelectorAll("[data-ui-theme-pick]").forEach((btn) => {
    const id = btn.getAttribute("data-ui-theme-pick");
    const active = id === current;
    btn.classList.toggle("is-active", active);
    btn.setAttribute("aria-selected", active ? "true" : "false");
  });
}

function pickAdminTheme(themeId) {
  if (!themeId) return;
  applyUiTheme(themeId, { announce: true });
}

function setupAdminThemePicker() {
  // Document-level capture: works even if a parent stops bubbling.
  if (document.documentElement.dataset.themePickerBound === "1") return;
  document.documentElement.dataset.themePickerBound = "1";
  document.addEventListener("click", (event) => {
    const btn = event.target?.closest?.("#adminThemeList [data-ui-theme-pick]");
    if (!btn) return;
    event.preventDefault();
    event.stopPropagation();
    pickAdminTheme(btn.getAttribute("data-ui-theme-pick"));
  }, true);
}

/** 설정 옵션 → 테마 변경 섹션의 「고대비 모드」 체크박스. */
function setupHighContrastToggle() {
  const box = $("highContrastToggle");
  if (!box) return;
  box.checked = localStorage.getItem(HIGH_CONTRAST_KEY) === "on";
  if (box.dataset.bound === "1") return;
  box.dataset.bound = "1";
  box.addEventListener("change", () => {
    applyHighContrastMode(box.checked);
  });
}

function setupUiThemeToggle() {
  try {
    syncElectronChrome();
  } catch (_) {
    /* ignore */
  }
  try {
    applyUiTheme(getUiTheme(), { announce: false });
  } catch (err) {
    console.warn("[supertory] applyUiTheme failed", err);
  }
  if (document.documentElement.dataset.themeToggleBound !== "1") {
    document.documentElement.dataset.themeToggleBound = "1";
    document.addEventListener("click", (event) => {
      const pickBtn = event.target?.closest?.("#uiThemeRail [data-ui-theme-rail-pick]");
      if (pickBtn) {
        event.preventDefault();
        event.stopPropagation();
        const id = pickBtn.getAttribute("data-ui-theme-rail-pick");
        if (id) applyUiTheme(id, { announce: true });
        closeUiThemeRail();
        return;
      }
      const toggleBtn = event.target?.closest?.("#uiThemeToggleButton");
      if (toggleBtn) {
        event.preventDefault();
        event.stopPropagation();
        toggleUiThemeRail();
        return;
      }
      if (isUiThemeRailOpen() && !event.target?.closest?.("#uiThemeRail, #binderThemeControl")) {
        closeUiThemeRail();
      }
    }, true);
    document.addEventListener("keydown", (event) => {
      if (event.key === "Escape" && isUiThemeRailOpen()) {
        closeUiThemeRail();
      }
    });
    window.addEventListener("resize", () => {
      if (isUiThemeRailOpen()) positionUiThemeRail();
    });
  }
  setupAdminThemePicker();
  setupHighContrastToggle();
  try {
    // Must call applyUiTheme (not setTheme): assigning window.setTheme = () => setTheme()
    // would recurse because top-level function setTheme is the same global slot.
    window.setTheme = (themeName) => applyUiTheme(themeName, { announce: true });
  } catch (_) {
    /* ignore */
  }
  try {
    renderAdminThemeList();
  } catch (_) {
    /* ignore */
  }
}

// Bind theme controls as soon as these helpers exist (before later init that may throw).
try {
  setupUiThemeToggle();
} catch (err) {
  console.warn("[supertory] setupUiThemeToggle failed", err);
}

function closeCreateMenu() {
  $("createMenuDropdown")?.classList.add("hidden");
  $("createMenuButton")?.setAttribute("aria-expanded", "false");
}

function openCreateMenu() {
  const menu = $("createMenuDropdown");
  const btn = $("createMenuButton");
  if (!menu) return;
  menu.classList.remove("hidden");
  btn?.setAttribute("aria-expanded", "true");
  // Binder clips absolute menus; pin to viewport when hosted in the left panel.
  if (menu.closest?.("#outlinePanel, .binder-work-meta")) {
    const ar = btn?.getBoundingClientRect?.();
    if (ar) {
      menu.style.position = "fixed";
      menu.style.top = `${Math.round(ar.bottom + 6)}px`;
      menu.style.left = `${Math.round(ar.left)}px`;
      menu.style.right = "auto";
      const rect = menu.getBoundingClientRect();
      if (rect.right > window.innerWidth - 8) {
        menu.style.left = `${Math.max(8, Math.round(window.innerWidth - rect.width - 8))}px`;
      }
      if (rect.bottom > window.innerHeight - 8) {
        menu.style.top = `${Math.max(8, Math.round(ar.top - rect.height - 6))}px`;
      }
    }
  } else {
    menu.style.position = "";
    menu.style.top = "";
    menu.style.left = "";
    menu.style.right = "";
  }
}

function toggleCreateMenu() {
  const menu = $("createMenuDropdown");
  if (!menu) return;
  if (menu.classList.contains("hidden")) openCreateMenu();
  else closeCreateMenu();
}

function setupCreateMenu() {
  $("createMenuButton")?.addEventListener("click", (event) => {
    event.stopPropagation();
    toggleCreateMenu();
  });
  $("createMenuDropdown")?.addEventListener("click", (event) => {
    const item = event.target.closest("[data-create-action]");
    if (!item) return;
    event.preventDefault();
    closeCreateMenu();
    const action = item.dataset.createAction;
    if (action === "new") createProject();
    else if (action === "import") openImportModal({ mode: "document" });
    else if (action === "import-proof") openImportModal({ mode: "proof" });
    else if (action === "export") openExportModal();
  });
  document.addEventListener("click", (event) => {
    if (!event.target.closest("#createMenu")) closeCreateMenu();
  });
  document.querySelectorAll("[data-close-export]").forEach((element) => {
    element.addEventListener("click", closeExportModal);
  });
  setupExportModalUi();
}

