document.addEventListener("keydown", (event) => {
  if (event.key !== "Escape") return;
  if (!$("adminModal")?.classList.contains("hidden")) {
    closeAdminModal();
    return;
  }
  if (!$("createMenuDropdown")?.classList.contains("hidden")) {
    closeCreateMenu();
    return;
  }
  if (!$("exportModal")?.classList.contains("hidden")) {
    closeExportModal();
    return;
  }
  if (!$("newProjectModal")?.classList.contains("hidden")) {
    closeNewProjectModal();
    return;
  }
  if (!$("textPromptModal")?.classList.contains("hidden")) {
    closeTextPromptModal(null);
    return;
  }
  if (!$("toryChatCharacterAllModal")?.classList.contains("hidden")) {
    closeToryChatCharacterAllModal();
    return;
  }
  if (!$("readerPersonaAllModal")?.classList.contains("hidden")) {
    closeReaderPersonaAllModal();
    return;
  }
  if (!$("characterAnalysisModal")?.classList.contains("hidden")) {
    closeCharacterAnalysisModal();
    return;
  }
  if (!$("importModal").classList.contains("hidden")) {
    closeImportModal();
    return;
  }
  if (!$("viewModeDropdown")?.classList.contains("hidden") || !$("splitModeDropdown")?.classList.contains("hidden")) {
    closeViewModeMenu();
    return;
  }
  if (!$("sceneToolsDrawer")?.classList.contains("hidden")) {
    closeSceneToolsDrawer();
    return;
  }
  hideDesktopContextMenu();
});
/** Bind click/change only when the node exists — missing DOM must not abort boot. */
function onEl(id, eventName, handler) {
  const el = $(id);
  if (!el || typeof el.addEventListener !== "function") return;
  el.addEventListener(eventName, handler);
}
function safeSetup(name, fn) {
  try {
    fn();
  } catch (err) {
    console.error(`[SuperTORY] setup failed: ${name}`, err);
  }
}

